 const cur=calM(),pers=pick(Object.keys(FPERS)),p=famMe(),job=pick(DJOB),fn=pick(sx==='M'?DMN:DFN),comp=Math.max(30,Math.min(98,Math.round(rnd(45,88)+(pers===p.pers?6:0))));
