function dtPropose(id){if(FAMBUSY)return;const F=S.fam,D=F.dt,p=famMe(),c=dtFind(id),cur=calM();closeModal();if(!c||c.st!=='dating'||p.sp||F.keys['wed:'+c.id])return;
 if(c.prog<75||c.dates<3||cur-c.since<3||cur-c.pr<3||S.cash<DCOST.ring+DCOST.wedding||!dtOK(c))return toast('Not ready to propose yet.','bad');FAMBUSY=true;
 try{if(!lspend(DCOST.ring,'Family','Engagement ring for '+c.fn,{to:'Jeweller'}))return;c.pr=cur;
  const chance=Math.max(.1,Math.min(.95,.35+c.comp/200+(c.prog-75)/100));
  if(Math.random()>=chance){c.prog=Math.max(0,c.prog-15);famEv(F,cur,'date',[F.pid],`You proposed to ${c.fn} ${c.sn}, but the answer was not yet. Ring bought for ${R(DCOST.ring)}.`,'rej:'+c.id+':'+cur,-DCOST.ring);dtDone();return toast(`💔 ${c.fn} said not yet. Try again in 3 months.`,'bad')}
  if(!lspend(DCOST.wedding,'Family','Wedding with '+c.fn,{to:'Wedding planner'}))return;
  const s=famAdd(F,{fn:c.fn,sn:c.sn,sx:c.sx,b:c.b,bd:c.bd,pers:c.pers,job:c.job,c:c.c,gen:p.gen,sp:p.id,hap:85,edu:pick(FEDU)});p.sp=s.id;D.cur=null;D.pool=D.pool.filter(x=>x.id!==c.id);
  F.mar.push({id:'MAR-'+String(F.mar.length+1).padStart(3,'0'),sp:s.id,m:cur,from:c.since,dates:c.dates,end:null});p.hap=Math.min(100,p.hap+10);
  famEv(F,cur,'wed',[p.id,s.id],`${p.fn} married ${s.fn} ${s.sn}. Ring ${R(DCOST.ring)} + wedding ${R(DCOST.wedding)}.`,'wed:'+c.id,-(DCOST.ring+DCOST.wedding));
  coin();dtDone();pop('💍 YOU ARE MARRIED!',`${esc(s.fn)} ${esc(s.sn)} has joined your family. You can now plan children in Family → Planning.`)}
 finally{FAMBUSY=false}}
function divMod(){const s=spouseOf(),F=S.fam;if(!s)return;const why=F.preg?'You cannot divorce while a baby is expected.':S.cash<DCOST.divorce?'You need '+R(DCOST.divorce)+' in cash for the legal fees.':'';
 modal(`<h2>💔 DIVORCE ${esc(s.fn.toUpperCase())}?</h2><p>Legal fees: <b>${R(DCOST.divorce)}</b> (paid from cash). ${esc(s.fn)} stays in your family record as ex-${s.sx==='F'?'wife':'husband'}; children keep both parents.</p>${kv('Your cash',R(S.cash))}${why?`<p class="r"><b>Not possible:</b> ${why}</p>`:''}<br><div class="row"><button class="btn s" onclick="closeModal()">KEEP MARRIAGE</button><button class="btn rd" ${why?'disabled':''} onclick="divGo()">DIVORCE</button></div>`)}
function divGo(){if(FAMBUSY)return;const F=S.fam,p=famMe(),s=spouseOf(),cur=calM();closeModal();if(!s||F.preg||S.cash<DCOST.divorce)return;const mr=F.mar.find(x=>!x.end&&x.sp===s.id);if(!mr||F.keys['div:'+mr.id])return;FAMBUSY=true;
 try{if(!lspend(DCOST.divorce,'Family','Divorce legal fees',{to:'Family court'}))return;mr.end={m:cur,t:'divorce'};p.sp=null;s.sp=null;s.ex=1;p.hap=Math.max(0,p.hap-15);
  famEv(F,cur,'split',[p.id,s.id],`${p.fn} and ${s.fn} ${s.sn} divorced after ${Math.max(0,cur-mr.m)} month(s) of marriage.`,'div:'+mr.id,-DCOST.divorce);dtDone();toast('Divorce finalised.')}finally{FAMBUSY=false}}
