function kidCan(){const F=S.fam,s=spouseOf(),cur=calM(),n=F.ppl.filter(c=>c.kid&&c.d==null).length;
 return!s?'You must be married to plan a child.':F.preg?'A baby is already expected.':n>=MAXKIDS?`Your family is full (${MAXKIDS} children).`:cur-F.lastKid<12?`Wait ${12-(cur-F.lastKid)} more month(s) after your last child.`:''}
