const dtBtn=(t,fn,dis,cls)=>`<button class="btn ${cls||'s'} sm" ${dis?'disabled':''} onclick="${fn}">${t}</button>`;
function dtCard(c){const cur=calM(),a=ageOf(c),F=S.fam,busy=F.dt.cur&&F.dt.cur!==c.id;let b='';
 if(c.st==='stranger')b=dtBtn('👋 MEET',`dtMeet('${c.id}')`);
 else{b=dtBtn('💬 TALK (free)',`dtTalk('${c.id}')`,c.la.t===cur)+dtBtn('☕ SPEND TIME '+R(DCOST.time),`dtSpend('${c.id}')`,c.la.s===cur);
  b+=c.st==='dating'?dtBtn('💕 GO ON A DATE '+R(DCOST.date),`dtAsk('${c.id}')`,c.la.d===cur)+dtBtn('💍 PROPOSE',`dtPropMod('${c.id}')`,false,'gr')+dtBtn('💔 END',`dtEndMod('${c.id}')`):dtBtn('💌 ASK ON A DATE '+R(DCOST.date),`dtAsk('${c.id}')`,c.la.d===cur||busy||c.prog<25)}
 return`<div class="card"><div class="pc">${avHtml(c)}<div class="info"><h3>${esc(c.fn)} ${esc(c.sn)} ${sp(c.st==='dating'?'Dating':c.st==='met'?'Acquaintance':'New','g')}</h3><p class="m">Age ${a} · ${esc(c.job)} · ${esc(c.pers)}</p><p>${esc(c.intro)}.</p></div></div>${kv('Compatibility',c.comp+'%')}<div class="bar" style="margin:4px 0"><i style="width:${c.comp}%;background:#2f80ed"></i></div>${c.st==='stranger'?'':kv('Relationship progress',c.prog+'/100')+`<div class="bar" style="margin:4px 0"><i style="width:${c.prog}%;background:#d6453d"></i></div>`}${c.st==='dating'?kv('Dates together',c.dates):''}<br><div class="row">${b}</div></div>`}
function dtView(){const F=S.fam,p=famMe(),a=ageOf(p),s=spouseOf();
 const top=`<div class="card"><h3>💕 DATING</h3>${kv('Your age',a)}${kv('Relationship status',famRelStatus())}${kv('Your cash',R(S.cash))}<p class="m">Each action can be used once per person per month. Meeting: max 2 new people a month. Dating costs come from your cash and appear in Transaction History.</p></div>`;
 if(s)return top+`<div class="card"><p>💍 You are married to <b>${esc(s.fn)} ${esc(s.sn)}</b>. Dating is closed. Visit <b>Planning</b> for children or divorce.</p></div>`;
 if(a<18)return top+'<div class="card"><p>You can start dating at 18.</p></div>';
 return top+dtPool().map(dtCard).join('')}
function fpView(){const F=S.fam,p=famMe(),s=spouseOf(),why=kidCan(),kids=F.ppl.filter(c=>c.kid),cur=calM();
 let h=`<div class="card"><h3>💍 MARRIAGE</h3>${s?kv('Spouse',esc(s.fn)+' '+esc(s.sn))+kv('Married',dateOf((F.mar.find(x=>!x.end&&x.sp===s.id)||{m:cur}).m))+kv('Happiness',s.hap+'%')+`<br><button class="btn rd sm" onclick="divMod()">DIVORCE</button>`:'<p class="m">You are not married. Start in the Dating tab.</p>'}</div>`;
 h+=`<div class="card"><h3>👶 CHILDREN (${kids.filter(c=>c.d==null).length}/${MAXKIDS})</h3>`;
 if(F.preg&&F.preg.rdy)h+=`<p><b>Your baby is here!</b> Choose a name to welcome the child.</p>${kidForm('birth')}<br><button class="btn gr" onclick="kidGo('birth','${F.preg.id}')">WELCOME THE BABY</button>`;
 else if(F.preg)h+=`<p>🤰 Expecting a baby due <b>${dateOf(F.preg.due)}</b> (${Math.max(0,F.preg.due-cur)} month(s) left).</p>`;
 else h+=(why?`<p class="m">${why}</p>`:'<p class="m">Choose how to grow your family. You will confirm and name the child first. Children are never added automatically.</p>')+`<div class="row">${dtBtn('👶 PLAN A BABY '+R(DCOST.birth),'birthMod()',!!why,'gr')}${dtBtn('🤝 ADOPT '+R(DCOST.adopt),'adoptMod()',!!why,'gr')}</div>`;
 h+='</div>';
 h+=`<div class="card"><h3>🎒 EDUCATION</h3>${kids.length?kids.map(c=>`<p>${c.d!=null?'🕯️':'🎒'} <b>${esc(c.fn)}</b> · ${c.d!=null?'Passed away':'Age '+ageOf(c)} · ${esc(c.edu)}</p>`).join(''):'<p class="m">Your children\'s schooling will appear here.</p>'}</div>`;
 h+=`<div class="card"><h3>📚 RELATIONSHIP HISTORY</h3>${F.mar.length?F.mar.map(x=>{const q=famGet(x.sp);return`<p>${x.end?'💔':'💍'} ${q?esc(q.fn)+' '+esc(q.sn):'?'} · married ${dateOf(x.m)}${x.end?', divorced '+dateOf(x.end.m):''}</p>`}).join(''):'<p class="m">No marriages yet. Dates, proposals and break-ups are in the Timeline.</p>'}</div>`;return h}
function lifeView(){famSync();const seg=`<div class="pills"><button class="${LS==='fam'?'on':''}" onclick="LS='fam';render()">👨‍👩‍👧 FAMILY LIFE</button><button class="${LS==='as'?'on':''}" onclick="LS='as';render()">🏡 ASSETS &amp; LIFESTYLE</button></div>`;
 if(LS==='as'){const tabs=[['ov','📊 Overview'],['vh','🚗 Vehicles'],['art','🖼️ Art'],['tr','✈️ Travel'],['ls','🏡 Lifestyle'],['ex','💸 Expenses'],['doc','📄 Documents']];return`<h2>🌴 My Life</h2>${seg}<div class="pills">${tabs.map(x=>`<button class="${LT===x[0]?'on':''}" onclick="LT='${x[0]}';render()">${x[1]}</button>`).join('')}</div>`+lifeTab()}
 const tabs=[['pf','👤 My Profile'],['fm','👨‍👩‍👧 Family'],['dt','💕 Dating'],['fp','👶 Planning'],['tl','📜 Timeline']],t=FMT==='mp'?'fm':FMT;
 return`<h2>🌴 My Life</h2>${seg}<div class="pills">${tabs.map(x=>`<button class="${t===x[0]?'on':''}" onclick="FMT='${x[0]}';render()">${x[1]}</button>`).join('')}</div>`+(FMT==='mp'?famMember():FMT==='fm'?famFamily():FMT==='tl'?famTimeline():FMT==='dt'?dtView():FMT==='fp'?fpView():famProfile())}
let S=load(),V='menu',AC=null;
function load(){try{const s=JSON.parse(localStorage.getItem(KEY)||(TESTMODE?localStorage.getItem(MAINKEY):null));if(s&&s.props){const g=Object.assign(fresh(),s);g.fin=Object.assign(finFresh(),s.fin||{});["loans","tx"].forEach(k=>{if(!Array.isArray(g.fin[k]))g.fin[k]=[]});if(!s.fin||g.fin.last==null)g.fin.last=g.cash;if(!s.fin||s.fin.v!==2)g.fin.lim=0;g.fin.v=2;if(!Array.isArray(g.fin.lh))g.fin.lh=[];g.M=Object.assign(zero(),s.M||{});g.lr=Number.isFinite(s.lr)?cl(s.lr):50;g.tn=Object.assign(tnFresh(),s.tn||{});["q","nx","news"].forEach(k=>{if(!Array.isArray(g.tn[k]))g.tn[k]=[]});g.props.forEach(p=>{const t=p.tenant;if(t){if(t.hap==null)t.hap=70;if(!t.pers)t.pers="Friendly";if(t.rl==null)t.rl=50}});g.bz=Object.assign(bzFresh(),s.bz||{});g.bz.st=Object.assign(bzFresh().st,(s.bz||{}).st||{});["list","q"].forEach(k=>{if(!Array.isArray(g.bz[k]))g.bz[k]=[]});g.bz.list.forEach(b=>{if(b.last==null)b.last={rev:0,exp:0,prof:0}});
 if(s.biz&&!g.bz.mig){let r=0;(s.biz.lands||[]).forEach(l=>{if(l.status==="AVAILABLE")r+=l.value});(s.biz.projects||[]).forEach(p=>{if(p.status==="UNDER CONSTRUCTION")r+=p.total;else if(p.status==="COMPLETED")r+=p.value});if(r>0){g.cash+=Math.round(r);g.tn.news.push("The old construction business was closed. Your land and projects were refunded: ₹"+Math.round(r).toLocaleString("en-IN")+".")}g.bz.mig=1}
 {const f=g.fin;if(!Number.isFinite(f.tn))f.tn=0;if(!f.sum)f.sum={rent:0,inc:0,exp:0};f.tx.slice().reverse().forEach(r=>{if(!r.id){r.id='TXN-'+String(++f.tn).padStart(6,'0');r.n=f.tn;r.k=catOf(r.t||'',r.a);r.st='COMPLETED';r.x={d:r.t};r.prev=null;r.cur=null;sumAdd(r,f.sum)}if(!r.x)r.x={}})}
{const L=g.life=Object.assign({own:[],trips:[],pts:0,spent:null,hist:[],art:[],next:1,hn:0},s.life||{});['own','trips','hist','art'].forEach(k=>{if(!Array.isArray(L[k]))L[k]=[]});if(!Number.isFinite(L.next))L.next=1;if(!Number.isFinite(L.hn))L.hn=0;
 L.own=L.own.map(o=>{const k=OLDK[o.k]||o.k,d=LF(k);if(d.n==='?')return null;return{id:o.id||L.next++,k,pp:Number.isFinite(o.pp)?o.pp:(OLDP[o.k]||d.p),m:Number.isFinite(o.m)?o.m:g.month,mm:Number.isFinite(o.mm)?o.mm:g.month}}).filter(Boolean);
 L.art=L.art.filter(a=>a&&ARTS.some(x=>x.k===a.k)&&Number.isFinite(a.val));L.trips=[...new Set(L.trips.map(k=>OLDT[k]||k))];
 if(L.spent==null){L.spent=0;g.fin.tx.forEach(r=>{if(r.k==='life'&&r.a<0)L.spent-=r.a})}}
bzMigrate(g);g.fam=famLoad(g,s.fam);g.rc=Object.assign({n:0,list:[]},s.rc||{});if(!Array.isArray(g.rc.list))g.rc.list=[];if(!Number.isFinite(g.rc.n))g.rc.n=0;delete g.biz;if(!Array.isArray(g.ach))g.ach=[];return g}}catch(e){}return fresh()}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}};
const tv=()=>S.props.reduce((a,p)=>a+p.value,0);
const gp=id=>S.props.find(p=>p.id===id);
function snd(f,d=.12){if(!S.sound)return;try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();const o=AC.createOscillator(),g=AC.createGain();o.frequency.value=f;g.gain.value=.08;o.connect(g);g.connect(AC.destination);o.start();g.gain.exponentialRampToValueAtTime(.0001,AC.currentTime+d);o.stop(AC.currentTime+d)}catch(e){}}
const coin=()=>{snd(880);setTimeout(()=>snd(1320),90)};
function toast(m,t=''){const d=document.createElement('div');d.className='toast '+t;d.textContent=m;$('#toasts').appendChild(d);setTimeout(()=>d.remove(),3000)}
function modal(h){const m=$('#modal');m.hidden=false;m.innerHTML=`<div class="sheet">${h}</div>`}
const closeModal=()=>{$('#modal').hidden=true};
const pop=(t,b)=>modal(`<h2>${t}</h2><p>${b}</p><br><button class="btn" onclick="closeModal()">OK</button>`);
