function tn(p){return{name:pick(NAMES),job:pick(JOBS),inc:Math.round(p.rent*rnd(2.2,4.5)/1000)*1000,rel:Math.max(40,Math.min(99,Math.floor(rnd(55,99)+(S.lr-50)*.25))),fam:Math.floor(rnd(1,6)),hap:Math.floor(rnd(60,86)),pers:pick(PERS),rl:Math.floor(rnd(40,61))}}
const prob=t=>Math.max(5,Math.min(99,Math.round(t.rel*.9+10+((t.hap==null?70:t.hap)-60)*.2+(S.lr-50)*.1)));
function mkBills(p,m=1){const o=p.tenant?1:.4,u=Math.round(p.e/8*rnd(.85,1.15)*o);p.u=u;
 p.bl={e:{a:Math.round(u*8*m),paid:0,by:'L'},w:{a:Math.round(p.w*rnd(.9,1.1)*o),paid:0,by:'L'},m:{a:p.m,paid:0,by:'L'}};setBy(p)}
function setBy(p){if(!p.tenant)return;if(p.contract.ep==='T'){p.bl.e.by='T';p.bl.e.paid=1}if(p.contract.wp==='T'){p.bl.w.by='T';p.bl.w.paid=1}}
function after(){finRec();bzChk();const sc=S.props.length*2+Math.floor(tv()/1e6)+Math.floor(S.st.rent/1e5)+Math.floor(S.st.months/3)+Math.max(0,Math.floor((S.st.rent-S.st.exp)/1e5));
 let l=1;LVS.forEach((x,i)=>{if(sc>=x)l=i+1});if(l>S.lvl){S.lvl=l;snd(660,.3);pop('⬆️ LEVEL UP!',`You are now a ${LV[l-1]}!`)}
 ACH.forEach((a,i)=>{if(!S.ach.includes(i)&&a[3](S)){S.ach.push(i);toast(`🏆 Achievement unlocked: ${a[1]}`,'good');snd(990,.3)}});save();render()}
function buy(k){const t=T.find(x=>x.k===k);if(S.cash<t.p){snd(200,.25);return toast('Not enough cash for this property. Use savings or a bank loan (Finance).','bad')}
 S.cash-=t.p;tx(-t.p,'Property Purchased: '+t.n,{k:'purchase',prop:t.n,d:'Property purchase'});const fl=Math.floor(rnd(1,t.h+1));const p={id:S.nid++,n:t.n,t:t.t,flat:fl*100+Math.floor(rnd(1,9)),price:t.p,value:t.p,rent:t.r,e:t.e,w:t.w,m:t.m,c:t.c,h:t.h,fl,tenant:null,contract:null,due:0,late:0,will:1,rn:0,ex:0,br:0};
 mkBills(p);S.props.push(p);S.st.bought++;coin();after();pop('🎉 PROPERTY PURCHASED!',`${t.n} - Flat ${p.flat} is now yours. Open My Properties and tap Manage Tenant to find a tenant.`)}
function findT(id){const p=gp(id);p.cands=[tn(p),tn(p),tn(p)];save();modal(`<h2>Find Tenant</h2><p class="m">Choose a tenant for ${p.n} - Flat ${p.flat}. Rent: ${R(p.rent)}</p><br>`+
 p.cands.map((t,i)=>`<div class="card"><h3>${t.name}</h3>${kv('Job',t.job)}${kv('Monthly income',R(t.inc))}${kv('Reliability',t.rel+'%')}${kv('Pays on time',prob(t)+'%')}${kv('Family size',t.fam)}${kv('Personality',t.pers)}<br><button class="btn gr" onclick="cMod(${id},${i})">SELECT</button></div>`).join('')+`<button class="btn s" onclick="closeModal()">CANCEL</button>`)}
const kv=(a,b)=>`<div class="kv"><span>${a}</span><b>${b}</b></div>`;
function cMod(id,i,view){const p=gp(id),t=view?p.tenant:p.cands[i],c=view?p.contract:{ep:'L',wp:'L',dep:p.rent*2,left:12,fee:2000};
 const sel=(n,v)=>view?`<b>${v==='T'?'Tenant':'Landlord'}</b>`:`<select id="${n}"><option value="L">Landlord</option><option value="T">Tenant</option></select>`;
 modal(`<div class="doc"><h3>🏠 RENTAL AGREEMENT</h3><br>${kv('Property',p.n+' - Flat '+p.flat)}${kv('Landlord','Player')}${kv('Tenant',t.name)}${kv('Monthly Rent',R(view?p.rent:rentRep(p)))}${kv('Security Deposit',R(c.dep))}${kv('Duration','12 months'+(view?` (${c.left} left)`:''))}${kv('Rent Due','1st of every month')}${kv('Late Fee',R(c.fee))}
 <div class="kv"><span>Electricity paid by</span>${sel('ep',c.ep)}</div><div class="kv"><span>Water paid by</span>${sel('wp',c.wp)}</div>${kv('Status',view?'ACTIVE':'DRAFT')}<p class="m"><br>Fictional in-game contract. Not real legal advice.</p></div>`+
 (view?`<button class="btn" onclick="closeModal()">CLOSE</button>`:`<div class="row"><button class="btn gr" onclick="sign(${id},${i})">SIGN CONTRACT</button><button class="btn s" onclick="closeModal()">CANCEL</button></div>`))}
function sign(id,i){const p=gp(id);p.tenant=p.cands[i];p.cands=null;p.contract={ep:$('#ep').value,wp:$('#wp').value,dep:p.rent*2,left:12,fee:2000};
 p.r0=p.r0||p.rent;p.rent=rentRep(p);p.due=p.rent;p.will=1;p.late=0;p.br=0;p.rn=0;p.ex=0;setBy(p);S.st.tenants++;coin();after();pop('📄 Contract Active',`${p.tenant.name} has moved in. The first month's rent of ${R(p.rent)} is due - tap Collect Rent.`)}
function tenantMod(id){const p=gp(id);if(!p.tenant)return findT(id);const t=p.tenant;
 modal(`<h2>👤 ${t.name}</h2>${kv('Job',t.job)}${kv('Monthly income',R(t.inc))}${kv('Reliability',t.rel+'%')}${kv('Pays on time',prob(t)+'%')}${kv('Family size',t.fam)}${hapRow(t)}${kv('Outstanding rent',R(p.due))}<br><div class="row"><button class="btn rd" onclick="endC(${id})">END CONTRACT</button><button class="btn s" onclick="closeModal()">CLOSE</button></div>`)}
function endC(id){const p=gp(id);if(p.due>0){const r=Math.min(p.contract.dep,p.due);S.cash+=r;S.M.rent+=r;S.st.rent+=r;tx(r,'Deposit applied to unpaid rent',{k:'rent',who:p.tenant.name,prop:p.n,flat:p.flat,pid:p.id,d:'Security deposit applied to unpaid rent'})}
 const n=p.tenant.name;p.tenant=null;p.contract=null;p.due=0;p.late=0;p.br=0;p.ex=0;snd(300,.25);after();pop('🚪 Tenant Left',`${n} moved out. ${p.n} is now 🏠 VACANT. Deposit covers any unpaid rent.`)}
function takeRent(p,fee=0){const a=p.due+fee;S.cash+=a;tx(a,'Rent Collected',{k:'rent',who:p.tenant.name,job:p.tenant.job,prop:p.n,flat:p.flat,pid:p.id,d:fee?'Monthly rent with late fee':'Monthly rent payment'});S.M.rent+=a;S.st.rent+=a;p.due=0;p.late=0;p.br=0;p.ex=0;p.rn=0;coin();return a}
function collect(id){const p=gp(id);if(!p.tenant)return toast('No tenant yet. Find one first.','bad');if(p.due<=0)return toast('No rent is due right now.');
 if(p.will){const pc=S.cash,a=takeRent(p);toast(`✓ RENT RECEIVED +${R(a)}`,'good');after();rcpt(p,pc,a)}else overdue(id)}
function overdue(id){const p=gp(id),late=p.late>=2||p.br;
 modal(`<h2>⚠️ PAYMENT OVERDUE</h2><p class="m">${p.tenant.name} has not paid this month's rent.</p>${kv('Tenant',p.tenant.name)}${kv('Amount',R(p.due))}${kv('Days overdue',p.late*30+5)}<br>
 <div class="row"><button class="btn" ${p.rn?'disabled':''} onclick="act('rem',${id})">SEND REMINDER</button><button class="btn" ${p.ex?'disabled':''} onclick="act('ext',${id})">GIVE EXTRA TIME</button><button class="btn rd" onclick="noticeMod(${id})">SEND LEGAL NOTICE</button></div>
 ${late?`<br><h3>🚨 CONTRACT BREACH</h3><p class="m">The tenant has failed to meet the rental agreement.</p><div class="row"><button class="btn s" onclick="closeModal()">WAIT</button><button class="btn" onclick="act('neg',${id})">NEGOTIATE</button><button class="btn rd" onclick="endC(${id})">END CONTRACT</button></div>`:'<br><button class="btn s" onclick="closeModal()">CLOSE</button>'}`)}
function noticeMod(id){const p=gp(id);modal(`<div class="doc"><h3>📄 RENT PAYMENT NOTICE</h3><br>${kv('Property',p.n+' - Flat '+p.flat)}${kv('Tenant',p.tenant.name)}${kv('Outstanding Rent',R(p.due))}<p>"According to the rental agreement, the outstanding rent must be paid within the specified period."</p>${kv('Deadline','7 days')}<p class="m"><br>Fictional game mechanic. Not real legal advice.</p></div><div class="row"><button class="btn rd" onclick="act('not',${id})">SEND NOTICE</button><button class="btn s" onclick="closeModal()">CANCEL</button></div>`)}
function act(a,id){const p=gp(id);closeModal();
 if(a==='rem'){p.rn=1;if(Math.random()<.55){RC=[p,S.cash,0];RC[2]=takeRent(p);toast('✅ Reminder worked. Rent received.','good')}else toast('Tenant says they will pay soon. Nothing received yet.')}
 if(a==='ext'){p.ex=1;toast('Extra time given. The tenant may pay by month end, with a late fee.')}
 if(a==='not'){if(Math.random()<.7){RC=[p,S.cash,0];RC[2]=takeRent(p);toast('✅ Notice worked. Rent received.','good')}else{p.br=1;toast('🚨 The tenant ignored the notice: contract breach.','bad')}}
 if(a==='neg'){const h=Math.round(p.due/2);S.cash+=h;S.M.rent+=h;S.st.rent+=h;tx(h,'Rent Collected',{k:'rent',who:p.tenant.name,job:p.tenant.job,prop:p.n,flat:p.flat,pid:p.id,d:'Partial rent after negotiation'});p.due-=h;p.late=0;p.br=0;p.will=1;toast(`🤝 Tenant pays ${R(h)} now and the rest later.`,'good');snd(700)}
 after();if(RC){const r=RC;RC=null;rcpt(r[0],r[1],r[2])}}
function pay(id,k){const p=gp(id),b=p.bl[k];if(b.paid)return;if(S.cash<b.a){snd(200,.25);return toast('Not enough cash to pay this bill.','bad')}
 S.cash-=b.a;tx(-b.a,({e:'Electricity Bill',w:'Water Bill',m:'Maintenance'})[k],{k:'expense',prop:p.n,flat:p.flat,to:({e:'Electricity provider',w:'Water supplier',m:'Maintenance contractor'})[k],d:({e:'Electricity bill',w:'Water bill',m:'Maintenance'})[k]});b.paid=1;S.M[{e:'el',w:'wa',m:'mt'}[k]]+=b.a;S.st.bills++;snd(440);toast(`Paid ${R(b.a)}`);after()}
function sellMod(id){const p=gp(id);modal(`<h2>SELL PROPERTY</h2><p>${p.n} - Flat ${p.flat}</p>${kv('Purchase Price',R(p.price))}${kv('Current Value',R(p.value))}${kv('Profit',`<span class="${p.value>=p.price?'g':'r'}">${R(p.value-p.price)}</span>`)}<br><div class="row"><button class="btn gr" onclick="sell(${id})">SELL</button><button class="btn s" onclick="closeModal()">CANCEL</button></div>`)}
function sell(id){const p=gp(id);S.cash+=p.value;tx(p.value,'Property Sold: '+p.n,{k:'sale',prop:p.n,flat:p.flat,buy:p.price,profit:p.value-p.price,d:'Property sale'});S.props=S.props.filter(x=>x.id!==id);S.st.sold++;coin();closeModal();after();toast(`Sold for ${R(p.value)}`,'good')}
function xfer(d){const a=Math.floor(+$('#amt').value);if(!(a>0))return toast('Enter an amount.','bad');
 if(d==='in'){if(a>S.cash)return toast('Not enough cash.','bad');S.cash-=a;S.bank+=a;S.M.saved+=a;tx(-a,'Savings Deposit',{k:'savings',sp:S.bank-a,sc:S.bank,d:'Transfer from cash to savings'})}else{if(a>S.bank)return toast('Not enough savings.','bad');S.bank-=a;S.cash+=a;S.M.saved-=a;tx(a,'Savings Withdrawal',{k:'savings',sp:S.bank+a,sc:S.bank,d:'Transfer from savings to cash'})}snd(500);after()}
function events(){if(Math.random()>.5)return;const o=S.props,tt=o.filter(p=>p.tenant),e=pick(['boom','elec','repair','perfect','diff','new']);
 if(e==='boom'&&o.length){const p=pick(o);p.value=Math.round(p.value*1.08);ev('🎉 PROPERTY VALUE BOOM',`${p.n} value up 8%.`)}
 else if(e==='elec'&&o.length){o.forEach(p=>p.bl.e.a=Math.round(p.bl.e.a*1.3));ev('⚡ ELECTRICITY PRICE INCREASE','Electricity bills are 30% higher this month.')}
 else if(e==='repair'&&o.length){const p=pick(o);S.cash-=8000;tx(-8000,'Repair: unexpected damage',{k:'expense',prop:p.n,flat:p.flat,to:'Repair service',d:'Unexpected repair'});S.M.other+=8000;ev('🔧 REPAIR REQUIRED',`Unexpected ₹8,000 repair at ${p.n}.`)}
 else if(e==='perfect'&&tt.length){const p=pick(tt);if(p.due>0)takeRent(p);ev('😊 PERFECT TENANT',`${p.tenant.name} paid rent early.`)}
 else if(e==='diff'&&tt.length){const p=pick(tt);p.will=0;ev('😡 DIFFICULT TENANT',`${p.tenant.name} is delaying payment.`)}
 else if(e==='new'&&!S.sky){S.sky=true;ev('🏢 NEW BUILDING RELEASED','Skyline Heights luxury apartments are now in the Market.')}}
function startMonth(){S.last=null;S.props.forEach(p=>{if(p.tenant){p.due+=p.rent;p.will=Math.random()*100<(p.late?45:prob(p.tenant));p.rn=0}mkBills(p)});events()}
function endMonth(){const M=S.M;let miss=0;bzMonth();
 S.props.forEach(p=>{if(p.tenant&&p.due>0){if(p.ex&&Math.random()<.7)takeRent(p,p.contract.fee);else{p.late++;if(p.late>=2)p.br=1}}p.ex=0;
  ['e','w','m'].forEach(k=>{const b=p.bl[k];if(!b.paid){const a=Math.round(b.a*1.05);S.cash-=a;tx(-a,'Auto-paid bill (5% late fee)',{k:'expense',prop:p.n,flat:p.flat,to:({e:'Electricity provider',w:'Water supplier',m:'Maintenance contractor'})[k],d:({e:'Electricity bill',w:'Water bill',m:'Maintenance'})[k]+' paid late with a 5% fee'});M[{e:'el',w:'wa',m:'mt'}[k]]+=a;b.paid=1;miss=1}});
  const o=p.value;p.value=Math.round(o*(1+rnd(-.015,.025)));if(p.value>o*1.015)toast(`📈 ${p.n} value increased!`);
  if(p.tenant&&--p.contract.left<=0){p.contract.left=12;toast(`${p.tenant.name} renewed the contract for 12 months.`)}});
 if(S.month%12===0&&S.props.length){M.other+=Math.round(tv()*.005)}
 if(S.month%12===0&&S.props.length){const x=Math.round(tv()*.005);S.cash-=x;tx(-x,'Annual property tax',{k:'expense',to:'City tax office',d:'Annual property tax'})}
 tnMonth();const up=lifeMonth();if(up)M.other+=up;
 const exp=M.el+M.wa+M.mt+M.other,net=M.rent+(M.cp||0)-exp;S.st.exp+=exp;S.st.months++;S.st.best=Math.max(S.st.best,net);S.clean=miss?0:S.clean+1;
 S.rep={m:S.month,...M,net};snd(600);after()}
function next(){S.rep=null;S.month++;S.M=zero();famSync();startMonth();closeModal();after();issueNext()}
function repModal(){const r=S.rep;modal(`<h2>📊 MONTHLY REPORT - Month ${r.m}</h2>${kv('Rent Received',`<span class="g">${R(r.rent)}</span>`)}${kv('Electricity',`<span class="r">-${R(r.el)}</span>`)}${kv('Water',`<span class="r">-${R(r.wa)}</span>`)}${kv('Maintenance',`<span class="r">-${R(r.mt)}</span>`)}${kv('Other, Tax & Upkeep',`<span class="r">-${R(r.other)}</span>`)}${kv('NET PROFIT',`<span class="${r.net>=0?'g':'r'}">${R(r.net)}</span>`)}<h3 style="margin-top:12px">📒 Finance Summary</h3>${kv('Monthly Income',R(r.rent+(r.biz||0)))}${kv('Monthly Expenses',R((r.el||0)+(r.wa||0)+(r.mt||0)+(r.other||0)))}${kv('Rental Income',R(r.rent))}${kv('Business Income',R(r.biz||0))}${kv('Business Profit',R(r.cp||0))}${kv('Loan Borrowed',R(r.loanIn||0))}${kv('Loan Repaid',R(r.loanOut||0))}${kv('Savings Added',R(r.saved||0))}${kv('Vehicle & Home Maintenance',R(r.lm||0))}<p class="m">Net Profit = rental income + business profit - expenses. Loans and savings are not profit. No interest is ever charged.</p><br><button class="btn gr" onclick="next()">CONTINUE TO NEXT MONTH</button>`)}
function reset(){if(confirm('Reset the game? All progress will be erased.')){S=fresh();save();V='menu';closeModal();render()}}
function go(v){V=v;render();scrollTo(0,0);if(v!=='menu'&&(S.tn.q.length||S.tn.news.length)&&$('#modal').hidden&&!S.rep)issueNext()}
function tutorial(){modal(`<h2>WELCOME TO PROPERTY EMPIRE 🏠</h2><p>You have ₹5,00,000. Your goal is to turn your savings into a property empire.</p><ol style="margin:10px 0 14px 20px"><li>Buy a property in the Market.</li><li>Open Properties and tap Find Tenant.</li><li>Pick a tenant and sign the rental contract.</li><li>Tap Collect Rent.</li><li>Pay electricity, water and maintenance bills.</li><li>Tap End Month, then save profit in Finance.</li><li>Buy your next property.</li><li>Spend profit in My Life: cars, boats, planes, homes and vacations.</li></ol><p class="m">Tip: if a tenant doesn't pay, send a reminder, give extra time or send a notice.</p><br><button class="btn" onclick="closeModal()">START INVESTING</button>`)}
function play(){go('home');if(!S.seen){S.seen=true;save();tutorial()}}
const bld=(c,h)=>`<div class="bld" style="--c:${c};--h:${h*12+22}px"></div>`;
function totals(){let r=0,x=0,n=0;S.props.forEach(p=>{if(p.tenant){r+=p.rent;n++}['e','w','m'].forEach(k=>{if(p.bl[k].by==='L')x+=p.bl[k].a})});return{r,x,n}}
function head(){return`<header><b>🏠 Property Empire</b><span class="gold">💰 ${R(S.cash)}</span><span>Lv${S.lvl} ${LV[S.lvl-1]}</span></header>`}
function nav(){return`<nav>${[['home','🏠','Home'],['props','🏢','Properties'],['market','🏪','Market'],['tenants','👥','Tenants'],['fin','📊','Finance'],['me','🌴','My Life']].map(x=>`<button class="${V===x[0]?'on':''}" onclick="go('${x[0]}')"><span>${x[1]}</span>${x[2]}</button>`).join('')}</nav>`}
const back=t=>`<button class="btn s sm" onclick="go('home')">⬅ Back</button><h2>${t}</h2>`;
function propCard(p){const bi=(k,ic,cl)=>{const b=p.bl[k];return`<div class="kv"><span>${ic}</span><span class="${cl}">${b.by==='T'?'Tenant pays':R(b.a)}</span>${b.paid?'<b>Paid ✅</b>':`<button class="btn sm" onclick="pay(${p.id},'${k}')">PAY</button>`}</div>`};
 const t=p.tenant,net=(t?p.rent:0)-['e','w','m'].reduce((a,k)=>a+(p.bl[k].by==='L'?p.bl[k].a:0),0);
 return`<div class="card"><div class="pc"><img class="pic" src="${IMG[p.ik||(T.find(x=>x.n===p.n)||T[0]).k]}" alt="${p.n}" width="84" height="100"><div class="info"><h3>🏠 ${p.n} <span class="m">${p.t} · Flat ${p.flat} · Floor ${p.fl}</span></h3>${kv('Tenant',t?t.name+' '+mood(t):'<span class="tag r">VACANT</span>')}${kv('Rent',t?R(p.rent)+'/month':R(p.rent)+' (vacant)')}${kv('Contract',t?'Active':'None')}${kv('Payment',!t?'-':p.due>0?`<span class="r">Due ${R(p.due)}</span>`:'Paid ✅')}${kv('Value',`${R(p.value)} <span class="${p.value>=p.price?'g':'r'}">${((p.value/p.price-1)*100).toFixed(1)}%</span>`)}${kv('Monthly Profit',`<span class="${net>=0?'g':'r'}">${R(net)}</span>`)}</div></div>
 ${bi('e','💡 Electricity ('+p.u+' units × ₹8)','y')}${bi('w','💧 Water','bl')}${bi('m','🔧 Maintenance','r')}<br>
 <div class="row"><button class="btn sm" onclick="tenantMod(${p.id})">👤 ${t?'MANAGE TENANT':'FIND TENANT'}</button>${t?`<button class="btn sm" onclick="cMod(${p.id},0,1)">📄 VIEW CONTRACT</button><button class="btn sm gr" onclick="collect(${p.id})">💰 COLLECT RENT</button>`:''}<button class="btn sm rd" onclick="sellMod(${p.id})">SELL</button></div></div>`}
const views={
menu:()=>`<div class="skyline">${bld('#6aa84f',3)}${bld('#e8a317',6)}${bld('#3b82c4',4)}${bld('#8a5cc2',7)}</div><h1>🏠 PROPERTY EMPIRE</h1><p>Build Your Rental Empire</p><button class="btn" onclick="play()">▶ PLAY</button><button class="btn s" onclick="tutorial()">❓ HOW TO PLAY</button><button class="btn s" onclick="go('ach')">🏆 ACHIEVEMENTS</button><button class="btn s" onclick="go('stats')">📊 STATISTICS</button><button class="btn s" onclick="go('set')">⚙ SETTINGS</button><span class="m" style="color:#bcd">Buy. Rent. Manage. Grow. · Sunrise City</span>`,
home:()=>{const t=totals(),net=t.r-t.x,due=S.props.filter(p=>p.tenant&&p.due>0).length,bills=S.props.reduce((a,p)=>a+['e','w','m'].filter(k=>!p.bl[k].paid).length,0),nx=LVS[S.lvl]||null,sc=nx?null:1;
 return`<div class="grid">${[['💰 Cash',R(S.cash),'gold'],['🏠 Properties',S.props.length,''],['👥 Tenants',t.n,''],['📈 Monthly Income',R(t.r),'g'],['💸 Monthly Expenses',R(t.x),'r'],['💵 Net Profit',R(net),net>=0?'g':'r']].map(c=>`<div class="chip"><small>${c[0]}</small><b class="${c[2]}">${c[1]}</b></div>`).join('')}</div><br>
 <div class="card"><h3>📅 Month ${S.month} · Sunrise City</h3><p class="m">${due?`🔔 ${due} rent payment(s) due. `:''}${bills?`${bills} bill(s) unpaid (auto-charged with a 5% fee at month end). `:''}${S.props.length?'':'Buy your first property in the Market.'}</p>${S.cash<0?'<p class="r">Your cash is negative. Withdraw savings or sell a property.</p>':''}<br><button class="btn gr" onclick="endMonth()">⏭ END MONTH ${S.month}</button></div>
 ${S.last?`<div class="card"><h3>${S.last.t}</h3><p>${S.last.b}</p></div>`:''}
 <div class="card"><h3>⭐ ${LV[S.lvl-1]}</h3><div class="bar"><i style="width:${Math.min(100,S.lvl>=5?100:Math.round((levelScore()-LVS[S.lvl-1])/(LVS[S.lvl]-LVS[S.lvl-1])*100))}%"></i></div></div>
 ${repHome()}${finHome()}${bzHome()}<div class="row"><button class="btn s" onclick="go('ach')">🏆 Achievements</button><button class="btn s" onclick="go('stats')">📈 Statistics</button><button class="btn s" onclick="go('set')">⚙ Settings</button><button class="btn s" onclick="tutorial()">❓ How to play</button></div>`},
props:()=>`<h2>🏢 My Properties</h2>${S.props.length?S.props.map(propCard).join(''):'<div class="card">You own no properties yet. Visit the Market!</div><button class="btn" onclick="go(\'market\')">🏪 GO TO MARKET</button>'}`,
market:()=>marketView(),
marketOld:()=>`<p class="m">Cash: ${R(S.cash)}</p><br>${T.filter(t=>t.k!=='sky'||S.sky||S.lvl>=3).map(t=>`<div class="card"><div class="pc"><img class="pic" src="${IMG[t.k]}" alt="${t.n}" width="84" height="100" loading="lazy"><div class="info"><h3>${t.n} — ${t.t}</h3>${kv('Price',R(t.p))}${kv('Monthly Rent',R(t.r))}${kv('💡 Electricity',R(t.e))}${kv('💧 Water',R(t.w))}${kv('🔧 Maintenance',R(t.m))}${kv('Expected Profit',`<span class="g">${R(t.r-t.e-t.w-t.m)}</span>`)}</div></div><br><button class="btn ${S.cash>=t.p?'gr':'s'}" onclick="buy('${t.k}')">BUY ${R(t.p)}</button></div>`).join('')}`,
tenants:()=>{const l=S.props.filter(p=>p.tenant);return`<h2>👥 Tenants</h2>${repCard()}${l.length?l.map(p=>`<div class="card"><h3>${p.tenant.name}</h3><p class="m">${p.n} - Flat ${p.flat}</p>${kv('Job',p.tenant.job)}${kv('Income',R(p.tenant.inc))}${kv('Reliability',p.tenant.rel+'%')}${kv('Family',p.tenant.fam)}${hapRow(p.tenant)}${kv('Rent',p.due>0?`<span class="r">Due ${R(p.due)}</span>`:'Paid ✅')}<br><button class="btn s" onclick="tenantMod(${p.id})">MANAGE TENANT</button></div>`).join(''):'<div class="card">No tenants yet. Buy a property and find a tenant.</div>'}`},
fin:()=>finView(),
finOld:()=>{const t=totals();return`<div class="card"><h3>💰 SAVINGS (your own money)</h3>${kv('Cash',R(S.cash))}${kv('Savings',R(S.bank))}<p class="m">Savings are protected and never spent automatically.</p><br><input id="amt" type="number" inputmode="numeric" placeholder="Amount (₹)"><br><br><div class="row"><button class="btn" onclick="xfer('in')">Cash ➜ Savings</button><button class="btn s" onclick="xfer('out')">Savings ➜ Cash</button></div></div>
 <div class="card"><h3>🏙️ Portfolio</h3>${kv('Total Properties',S.props.length)}${kv('Total Property Value',R(tv()))}${kv('Monthly Rent',R(t.r))}${kv('Monthly Expenses',R(t.x))}${kv('Monthly Profit',`<span class="${t.r-t.x>=0?'g':'r'}">${R(t.r-t.x)}</span>`)}</div><button class="btn s" onclick="go('stats')">📈 STATISTICS</button>`},
me:()=>lifeView(),
ach:()=>back('🏆 Achievements')+ACH.map((a,i)=>`<div class="card" style="opacity:${S.ach.includes(i)?1:.55}"><h3>${a[0]} ${a[1]} ${S.ach.includes(i)?'✅':'🔒'}</h3><p class="m">${a[2]}</p></div>`).join(''),
stats:()=>{const s=S.st;return back('📊 Statistics')+`<div class="card">${kv('Total Rent Collected',R(s.rent))}${kv('Total Expenses',R(s.exp))}${kv('Total Profit',R(s.rent-s.exp))}${kv('Properties Bought',s.bought)}${kv('Properties Sold',s.sold)}${kv('Tenants Managed',s.tenants)}${kv('Bills Paid',s.bills)}${kv('Months Completed',s.months)}${kv('Highest Monthly Profit',R(s.best))}${kv('Total Property Value',R(tv()))}</div>`},
set:()=>back('⚙ Settings')+`<div class="card"><button class="btn s" onclick="S.sound=!S.sound;snd(600);save();render()">🔊 Sound: ${S.sound?'ON':'OFF'}</button><br><br><button class="btn gr" onclick="save();toast('Game saved','good')">💾 SAVE GAME</button><br><br><button class="btn rd" onclick="reset()">RESET GAME</button><p class="m"><br>Fictional simulation. No real banks, accounts or legal advice. Progress also saves automatically.</p></div>${V==='set'&&true?'<button class="btn s" onclick="go(\'menu\')">Main menu</button>':''}`};
function levelScore(){return S.props.length*2+Math.floor(tv()/1e6)+Math.floor(S.st.rent/1e5)+Math.floor(S.st.months/3)+Math.max(0,Math.floor((S.st.rent-S.st.exp)/1e5))}
function render(){const g=V!=='menu',fl=['ach','stats','set'].includes(V);$('#app').innerHTML=(g?head():'')+`<main class="${V}">${views[V]()}</main>`+(g&&!fl?nav():'');
 if(S.rep&&g)repModal()}
if(!S.props.every(p=>p.bl))S.props.forEach(p=>{if(!p.bl)mkBills(p)});
/* ===== FINANCE: existing savings + interest-free bank loans, overview, history ===== */
let FT='bank';
const fDebt=()=>S.fin.loans.reduce((a,l)=>a+(l.amt-l.rep),0),nw=()=>assets()-fDebt(),fTier=()=>Math.min(6,Math.max(S.lvl-1,bLvl()-1));
// Debt limit follows the existing player level and business level (the higher of the two); it never goes down.
function loanLimit(){S.fin.lim=Math.max(S.fin.lim||0,DL[fTier()]);return S.fin.lim}
// Total Assets = cash + savings + property value + business/construction value (land, finished and in-progress projects)
function assets(){return S.cash+S.bank+tv()+S.bz.list.reduce((a,b)=>a+bzVal(b),0)+lifeAssets()}
// Activity log: tx() records a known money move; finRec() logs any other cash change so the log always matches cash.
/* ===== TRANSACTION HISTORY: every money move is recorded with an ID, category and receipt ===== */
let TF='all',TQ='';
function catOf(t,a){return /Rent Collected|Deposit applied/.test(t)?'rent':/Bank Loan/.test(t)?'loan':/Loan Repayment/.test(t)?'repay':/Property Purchased/.test(t)?'purchase':/Property Sold/.test(t)?'sale':/Savings|Moved to|Withdrawn/.test(t)?'savings':/Business Purchased/.test(t)?'bizbuy':/monthly profit|Group booking|Late rent/.test(t)?'bizinc':/Vacation|Purchase:|Sold:|upkeep/.test(t)?'life':/Other Income|Bills & Other/.test(t)?'other':a<0?'expense':'other'}
// Summary rules: loans, repayments, savings moves and property/business purchases and sales are NOT income or expenses.
function sumAdd(r,s){const x=r.x||{};if(r.k==='rent'){s.rent+=r.a;s.inc+=r.a}else if(r.k==='bizinc'){s.inc+=x.gross!=null?x.gross:Math.max(0,r.a);s.exp+=x.exp!=null?x.exp:Math.max(0,-r.a)}else if(r.k==='expense'||r.k==='life'){if(r.a<0)s.exp-=r.a}else if(r.k==='other'){if(r.a>0)s.inc+=r.a;else s.exp-=r.a}}
// Shared recorder: call right after a successful money change (cash already updated). Returns the record.
function tx(a,t,m){const f=S.fin;a=Math.round(a);m=m||{};const cur=S.cash,r={id:'TXN-'+String(++f.tn).padStart(6,'0'),n:f.tn,m:S.month,a,t,k:m.k||catOf(t,a),st:'COMPLETED',prev:cur-a,cur,x:m};f.tx.unshift(r);if(f.tx.length>500)f.tx.length=500;sumAdd(r,f.sum);f.last=(f.last==null?S.cash:f.last)+a;return r}
function finRec(){const f=S.fin;if(f.last==null)f.last=S.cash;const d=S.cash-f.last;if(d){const r={id:'TXN-'+String(++f.tn).padStart(6,'0'),n:f.tn,m:S.month,a:d,t:d>0?'Other Income':'Bills & Other Expenses',k:'other',st:'COMPLETED',prev:f.last,cur:S.cash,x:{d:d>0?'Other income':'Other bills and expenses'}};f.tx.unshift(r);if(f.tx.length>500)f.tx.length=500;sumAdd(r,f.sum);f.last=S.cash}loanLimit()}
const TL={rent:'RENT RECEIVED',loan:'LOAN TAKEN',repay:'LOAN REPAYMENT',purchase:'PROPERTY PURCHASED',sale:'PROPERTY SOLD',bizbuy:'BUSINESS PURCHASED',bizinc:'BUSINESS INCOME',bizinv:'BUSINESS INVESTMENT',bizsale:'BUSINESS PROPERTY SOLD',bizref:'BUSINESS REFUND',expense:'EXPENSE PAID',life:'PERSONAL SPENDING',savings:'SAVINGS TRANSFER',other:'OTHER'};
const tLbl=r=>r.k==='bizinc'&&r.a<0?'BUSINESS LOSS':r.k==='savings'?(r.a<0?'SAVINGS DEPOSIT':'SAVINGS WITHDRAWAL'):r.k==='expense'&&r.x.biz?'BUSINESS EXPENSE':r.k==='other'?(r.a>0?'OTHER INCOME':'OTHER EXPENSE'):r.k==='asset'?(r.a<0?'ASSET PURCHASED':'ASSET SOLD'):r.k==='life'&&r.a>0?'PERSONAL ITEM SOLD':TL[r.k]||'TRANSACTION';
const tMatch=(r,f)=>f==='all'||(f==='inc'&&(r.k==='rent'||(r.k==='bizinc'&&r.a>0)||(r.k==='other'&&r.a>0)))||(f==='exp'&&(r.k==='expense'||(r.k==='life'&&r.a<0)||(r.k==='bizinc'&&r.a<0)||(r.k==='other'&&r.a<0)))||(f==='rent'&&r.k==='rent')||(f==='loan'&&(r.k==='loan'||r.k==='repay'))||(f==='prop'&&(r.k==='purchase'||r.k==='sale'))||(f==='biz'&&(r.k==='bizinc'||r.k==='bizbuy'||r.k==='bizinv'||r.k==='bizsale'||r.k==='bizref'||!!r.x.biz))||(f==='sav'&&r.k==='savings')||(f==='life'&&(r.k==='life'||r.k==='asset'));
function tListHtml(){const q=TQ.trim().toLowerCase(),all=S.fin.tx,l=all.filter(r=>tMatch(r,TF)&&(!q||[r.id,r.t,r.x.who,r.x.prop,r.x.biz,r.x.loan].join(' ').toLowerCase().includes(q)));
 if(!all.length)return'<div class="card">No transactions yet. Your financial activity will appear here.</div>';if(!l.length)return'<div class="card">No matching transactions.</div>';
 let h='',cm=null;l.slice(0,150).forEach(r=>{if(r.m!==cm){cm=r.m;h+=`<h3 style="margin:12px 0 6px">📅 Month ${cm}</h3>`}
  const x=r.x,cl2=r.k==='savings'?'':r.a>=0?'g':'r',who=x.who||x.to||'',where=x.prop?x.prop+(x.flat?' — Flat '+x.flat:''):x.biz||x.loan||'';
  h+=`<div class="card"><div class="kv"><b>${tLbl(r)}</b><b class="${cl2}">${r.a>=0?'+':'−'}${R(Math.abs(r.a))}</b></div><p>${x.d||r.t}</p>${where||who?`<p class="m">${[where,who].filter(Boolean).join(' · ')}</p>`:''}<p class="m">${r.id} · Month ${r.m} · ${r.st}</p><button class="btn s sm" onclick="txView('${r.id}')">VIEW RECEIPT</button></div>`});
 return h+(l.length>150?'<p class="m">Showing the latest 150 matching transactions.</p>':'')}
function tRefresh(){$('#tlist').innerHTML=tListHtml()}
function txTab(){const s=S.fin.sum,net=s.inc-s.exp,ps=[['all','All'],['inc','Income'],['exp','Expenses'],['rent','Rent'],['loan','Loans'],['prop','Property'],['biz','Business'],['sav','Savings'],['life','Personal']];
 return`<div class="card"><h3>📜 TRANSACTION HISTORY</h3>${kv('Total Income Received',`<b class="g">${R(s.inc)}</b>`)}${kv('Total Expenses Paid',`<b class="r">${R(s.exp)}</b>`)}${kv('Total Rent Received',R(s.rent))}${kv('Total Loan Borrowed',R(S.fin.borrowed))}${kv('Total Loan Repaid',R(S.fin.repaid))}${kv('Net Operating Cash Flow',`<b class="${net>=0?'g':'r'}">${R(net)}</b>`)}<p class="m">Loans, repayments, savings moves and property or business purchases and sales are not counted as income or expenses.</p></div><div class="pills">${ps.map(p=>`<button class="${TF===p[0]?'on':''}" onclick="TF='${p[0]}';render()">${p[1]}</button>`).join('')}</div><input placeholder="Search ID, tenant, property or business" value="${TQ.replace(/"/g,'&quot;')}" oninput="TQ=this.value;tRefresh()"><br><br><div id="tlist">${tListHtml()}</div>`}
function txView(id){const r=S.fin.tx.find(z=>z.id===id);if(!r)return;if(r.k==='rent'&&r.rc){const c=S.rc.list.find(z=>z.no===r.rc);if(c)return rcView(c)}
 const x=r.x,u=x.flat?'Flat '+x.flat:null,P=v=>v!=null&&Number.isFinite(v)?R(v):null,rows=[['Transaction Type',tLbl(r).toLowerCase().replace(/(^|\s)\w/g,c=>c.toUpperCase())],['Game Date','Month '+r.m],['Description',x.d||r.t]];
 const add=(a,b)=>{if(b!=null&&b!=='')rows.push([a,b])};
 if(r.k==='rent'){add('Received From',x.who);add('Property',x.prop);add('Unit',u)}
 if(r.k==='loan'){add('Bank','Property Empire Bank');add('Loan',x.loan);add('Interest','₹0');add('Total Repayment',R(r.a));add('Outstanding Loan After',P(x.out))}
 if(r.k==='repay'){add('Paid To','Property Empire Bank');add('Interest','₹0');add('Outstanding Before',P(x.ob));add('Outstanding After',P(x.oa))}
 if(r.k==='expense'||r.k==='life'){add('Paid To',x.to);add('Property',x.prop);add('Unit',u);add('Business',x.biz);add('Requested By',x.who)}
 if(r.k==='asset'){add('Item',x.item);add('Category',x.cat);add('Purchase Price',P(x.pp));if(r.a>0){add('Sale Proceeds',R(r.a));if(x.pp!=null)add('Gain / Loss vs Purchase',(r.a-x.pp>=0?'+':'−')+R(Math.abs(r.a-x.pp)))}}
 if(r.k==='life'){add('Category',x.cat);add('Destination',x.dest)}
 if(x.items)x.items.forEach(i=>add(i.n,R(i.c)));
 if(r.k==='purchase'||r.k==='bizbuy'){add('Property',x.prop);add('Business',x.biz)}
 if(r.k==='sale'){add('Property',x.prop);add('Unit',u);add('Sale Proceeds',R(r.a));add('Original Purchase Price',P(x.buy));if(P(x.profit)!=null)add('Profit / Loss',(x.profit>=0?'+':'−')+R(Math.abs(x.profit)))}
 if(r.k==='bizinv'){add('Business',x.biz);add('Property',x.prop);add('Paid To',x.to)}
  if(r.k==='bizsale'){add('Business',x.biz);add('Property',x.prop);add('Sale Proceeds',R(r.a));add('Purchase Price',P(x.buy));add('Renovation Spent',P(x.reno));add('Profit / Loss',(x.profit>=0?'+':'−')+R(Math.abs(x.profit)))}
  if(r.k==='bizref'){add('Business',x.biz)}
  if(r.k==='bizinc'){add('Business',x.biz);add('Income Source',x.src);add('Received From',x.who);add('Gross Income',P(x.gross));add('Expenses',P(x.exp));if(x.gross!=null)add('Net Profit',(r.a>=0?'+':'−')+R(Math.abs(r.a)))}
 if(r.k==='savings'){add('Previous Savings',P(x.sp));add('Resulting Savings',P(x.sc))}
 rows.push(['Amount',(r.a>=0?'+':'−')+R(Math.abs(r.a))]);if(r.prev!=null){rows.push(['Previous Cash',R(r.prev)]);rows.push(['Current Cash',R(r.cur)])}
 modal(`<div class="rcpt"><div class="rc-h"><small>PROPERTY EMPIRE</small><h2>Transaction Receipt</h2></div><div class="rc-m"><span>Transaction ID: ${r.id}</span><span>Month ${r.m}</span></div>${rows.map(z=>`<div class="rc-r"><span>${z[0]}</span><b>${z[1]}</b></div>`).join('')}<div class="rc-ok">${r.st}</div><p class="rc-th">Thank you for playing Property Empire.</p><button class="btn" onclick="closeModal()">CLOSE</button></div>`)}
function lhAdd(t,a){const f=S.fin;f.lh.unshift({m:S.month,t,a,rem:fDebt()});if(f.lh.length>100)f.lh.length=100}
function loanMod(i){const L=LOANS[i],d=fDebt(),lim=loanLimit();if(!L||!L.ok())return toast('Locked: '+L.req+'.','bad');if(d+L.a>lim)return toast('Above your debt limit. Repay some debt first.','bad');
 const w=[],t=totals();if(d>0)w.push('You already have significant outstanding debt.');if(d+L.a>lim*.5)w.push('Taking a large loan will increase your financial risk.');if(t.r-t.x<L.a/30)w.push('Make sure your rental income can support your repayments.');
 modal(`<h2>TAKE ${L.n.toUpperCase()}?</h2>${kv('Loan Amount',R(L.a))}${kv('Interest','₹0')}${kv('Total Repayment',R(L.a))}${kv('Outstanding Debt After Loan',`<b class="r">${R(d+L.a)}</b>`)}${kv('Cash After Loan',R(S.cash+L.a))}${w.length?`<p class="m"><br>⚠️ ${w.slice(0,2).join('<br>⚠️ ')}</p>`:''}<br><div class="row"><button class="btn s" onclick="closeModal()">CANCEL</button><button class="btn gr" onclick="takeLoan(${i})">TAKE LOAN</button></div>`)}
function takeLoan(i){const L=LOANS[i],f=S.fin;if(!L||!L.ok()||fDebt()+L.a>loanLimit()){closeModal();return toast('This loan is not available right now.','bad')}
 S.cash+=L.a;f.loans.push({id:f.nid++,amt:L.a,rep:0,status:'ACTIVE',m:S.month,n:L.n});f.borrowed+=L.a;S.M.loanIn+=L.a;tx(L.a,'Bank Loan Received',{k:'loan',loan:L.n,out:fDebt(),d:L.n+' received'});lhAdd('Loan Taken',L.a);coin();closeModal();after();
 pop('🏦 Loan Approved!',`${R(L.a)} has been added to your available funds.<br>Outstanding Loan: <b class="r">${R(fDebt())}</b>`)}
function repayMod(a){const d=fDebt();if(d<=0)return toast("You don't have an active loan.");const x=a==='full'?d:Math.min(a,d);if(!(x>0))return toast('Enter a valid amount.','bad');if(S.cash<x){snd(200,.25);return toast('Insufficient funds.','bad')}
 modal(`<h2>REPAY LOAN?</h2>${kv('Repayment',R(x))}${kv('Remaining Loan',R(d-x))}${kv('Cash After Repayment',R(S.cash-x))}${a!=='full'&&a>d?'<p class="m">Limited to your remaining loan.</p>':''}<br><div class="row"><button class="btn s" onclick="closeModal()">CANCEL</button><button class="btn gr" onclick="doRepay(${x})">REPAY</button></div>`)}
function repayCustom(){const v=Math.floor(Number($('#ramt').value));repayMod(v>0?v:0)}
function doRepay(a){const f=S.fin;a=Math.min(Math.floor(a),fDebt());if(!(a>0))return closeModal();if(S.cash<a){closeModal();return toast('Insufficient funds.','bad')}
 S.cash-=a;let r=a;f.loans.filter(l=>l.status==='ACTIVE').forEach(l=>{const x=Math.min(r,l.amt-l.rep);l.rep+=x;r-=x;if(l.rep>=l.amt){l.status='PAID';l.pm=S.month}});f.repaid+=a;S.M.loanOut+=a;tx(-a,'Loan Repayment',{k:'repay',ob:fDebt()+a,oa:fDebt(),d:'Loan repayment'});
 const done=fDebt()===0;lhAdd(done?'Loan Fully Repaid':'Loan Repayment',a);coin();closeModal();after();
 if(done)pop('✅ Loan fully repaid!','Outstanding Loan: ₹0. Your financial record has improved.');else toast(`Repaid ${R(a)}. Remaining loan: ${R(fDebt())}`,'good')}
function finHome(){const d=fDebt();return`<div class="card"><h3>💰 FINANCIAL STATUS</h3>${kv('Cash',R(S.cash))}${kv('Savings',R(S.bank))}${kv('Debt',`<span class="${d?'r':''}">${R(d)}</span>`)}${kv('Net Worth',`<b>${R(nw())}</b>`)}<br><button class="btn s" onclick="go('fin')">VIEW FINANCE</button></div>`}
function finTab(){const f=S.fin,d=fDebt(),lim=loanLimit(),av=Math.max(0,lim-d),t=totals();
 if(FT==='bank')return`<div class="card"><h3>🏦 BANK</h3>${kv('Available Cash',R(S.cash))}${kv('Savings',R(S.bank))}${kv('Outstanding Loan',`<span class="${d?'r':''}">${R(d)}</span>`)}${kv('Total Assets',R(assets()))}${kv('Net Worth',`<b>${R(nw())}</b>`)}${kv('Monthly Income',`<span class="g">${R(t.r)}</span>`)}${kv('Monthly Expenses',`<span class="r">${R(t.x)}</span>`)}${kv('Monthly Profit',`<span class="${t.r-t.x>=0?'g':'r'}">${R(t.r-t.x)}</span>`)}${kv('Finance Level',sp(FL[fTier()],'g'))}${S.cash<50000?'<p class="r">⚠️ Your available cash is low.</p>':''}${d>lim*.5?'<p class="r">⚠️ You already have significant outstanding debt.</p>':''}</div>
 <div class="card"><p><b>💰 SAVINGS</b> = your own saved money.</p><p><b>🏦 BANK LOAN</b> = borrowed money that you must repay. No interest.</p><br><div class="row"><button class="btn" onclick="FT='sav';render()">💰 SAVINGS</button><button class="btn gr" onclick="FT='loans';render()">💳 LOANS</button></div></div>`;
 if(FT==='sav')return views.finOld();
 if(FT==='loans'){const act=f.loans.filter(l=>l.status==='ACTIVE'),o=act.reduce((a,l)=>a+l.amt,0),rp=act.reduce((a,l)=>a+l.rep,0);
  return`<div class="card"><h3>💳 BANK LOANS</h3>${kv('Current Debt',R(d))}${kv('Debt Limit',R(lim))}${kv('Available Borrowing',`<b class="g">${R(av)}</b>`)}${kv('Interest','₹0')}<p class="m">Optional, interest-free, and repaid at exactly the amount borrowed.</p></div>`+
  LOANS.map((L,i)=>{const ok=L.ok(),fit=d+L.a<=lim;return`<div class="card" style="${ok?'':'opacity:.65'}"><h3>${L.n}</h3>${kv('Amount',`<b>${R(L.a)}</b>`)}${kv('Interest','₹0')}${kv('Total Repayment',R(L.a))}<br>${!ok?sp('🔒 '+L.req):!fit?sp('Over your debt limit','r'):`<button class="btn gr" onclick="loanMod(${i})">TAKE LOAN</button>`}</div>`}).join('')+
  (d>0?`<div class="card"><h3>ACTIVE LOAN</h3>${kv('Original Amount',R(o))}${kv('Interest','₹0')}${kv('Outstanding',`<b class="r">${R(d)}</b>`)}${kv('Amount Repaid',R(rp))}<br><div class="grid">${[10000,25000,50000,100000].map(a=>`<button class="btn s" onclick="repayMod(${a})">REPAY ${R(a)}</button>`).join('')}</div><br><input id="ramt" type="number" inputmode="numeric" placeholder="Custom amount (₹)"><br><br><div class="row"><button class="btn" onclick="repayCustom()">REPAY CUSTOM</button><button class="btn gr" onclick="repayMod('full')">REPAY FULL ${R(d)}</button></div></div>`:'<div class="card">You don\'t have an active loan.</div>')}
 if(FT==='ov'){const pv=tv(),bv=S.bz.list.reduce((a,b)=>a+bzVal(b),0);return`<div class="card"><h3>📊 FINANCIAL OVERVIEW</h3>${kv('Cash',R(S.cash))}${kv('Savings',R(S.bank))}${kv('Property Value',R(pv))}${kv('Business Value',R(bv))}${kv('Personal Assets (vehicles, homes, art)',R(lifeAssets()))}${kv('Total Assets',`<b>${R(assets())}</b>`)}${kv('Outstanding Loans',`<span class="${d?'r':''}">${R(d)}</span>`)}${kv('Total Debt',`<span class="${d?'r':''}">${R(d)}</span>`)}${kv('Net Worth',`<b class="${nw()>=0?'g':'r'}">${R(nw())}</b>`)}<p class="m">Net Worth = Total Assets - Outstanding Loans. Taking a loan adds cash and debt equally, so it does not change your net worth.</p></div>`}
 if(FT==='rc')return rcList();
 if(FT==='lh')return`<div class="card"><h3>🧾 LOAN HISTORY</h3>${kv('Total Borrowed',R(f.borrowed))}${kv('Total Repaid',R(f.repaid))}</div>`+(f.lh.length?f.lh.slice(0,60).map(x=>`<div class="card"><h3>${x.t}</h3>${kv('Game Month','Month '+x.m)}${kv('Amount',`<b class="${x.t==='Loan Taken'?'g':'r'}">${R(x.a)}</b>`)}${kv('Remaining Loan',R(x.rem))}</div>`).join(''):'<div class="card">No loan activity yet.</div>');
 return txTab()}
function finView(){const tabs=[['bank','🏦 Bank'],['sav','💰 Savings'],['loans','💳 Loans'],['ov','📊 Overview'],['lh','🧾 Loan History'],['tx','📜 Transactions'],['rc','🧾 Rent Receipts']];
 return`<h2>💰 Finance</h2><div class="pills">${tabs.map(x=>`<button class="${FT===x[0]?'on':''}" onclick="FT='${x[0]}';render()">${x[1]}</button>`).join('')}</div>`+finTab()}

/* ===== TENANT DIALOGUE, MAINTENANCE & LANDLORD REPUTATION ===== */
const repLbl=v=>v<25?'Poor':v<45?'Fair':v<65?'Good':v<85?'Great':'Excellent',relLbl=v=>v<30?'Tense':v<55?'Neutral':v<80?'Friendly':'Trusted';
const mood=t=>t.hap>=65?'😊':t.hap>=40?'😐':'😠',hapCol=h=>h>=65?'#1f9d62':h>=40?'#e8a317':'#d6453d';
const rentRep=p=>Math.round((p.r0||p.rent)*(1+(S.lr-50)/500)/100)*100;
const hapRow=t=>kv('Personality',t.pers||'Friendly')+kv('Happiness',`${mood(t)} ${t.hap}%`)+`<div class="bar" style="margin:4px 0"><i style="width:${t.hap}%;background:${hapCol(t.hap)}"></i></div>`+kv('Relationship With You',relLbl(t.rl))+kv('Reliability',t.rel+'%');
const bump=(t,h,r)=>{t.hap=cl(t.hap+h);t.rl=cl(t.rl+r)};
const tnCh=p=>{const t=p.tenant;return Math.max(.04,Math.min(.55,.16+(55-t.hap)/260+(50-S.lr)/450+({Demanding:.08,Calm:-.05,Chatty:.02}[t.pers]||0)))};
function mkIssue(p){const i=pick(ISS),big=p.big;p.big=0;return{id:S.tn.nid++,pid:p.id,t:i.t,m:i.m,c:Math.max(300,Math.round(i.c*(.6+p.rent/40000)/100)*100)*(big?2:1),d:0,big:!!big}}
function tnIgnore(p){if(p&&p.tenant){bump(p.tenant,-14,-8);p.big=1}S.lr=cl(S.lr-3)}
function tnLeave(p,why){const t=p.tenant;if(p.due>0){const r=Math.min(p.contract.dep,p.due);S.cash+=r;S.M.rent+=r;S.st.rent+=r;tx(r,'Deposit applied to unpaid rent',{k:'rent',who:t.name,prop:p.n,flat:p.flat,pid:p.id,d:'Security deposit applied to unpaid rent'})}
 S.tn.news.push(`<b>${t.name}</b> moved out of ${p.n}: ${why}. The property is now vacant.`);p.tenant=null;p.contract=null;p.due=0;p.late=0;p.br=0;p.ex=0;p.big=0;S.lr=cl(S.lr-4);
 S.tn.nx=S.tn.nx.filter(x=>x.pid!==p.id);S.tn.q=S.tn.q.filter(x=>x.pid!==p.id);snd(300,.25)}
// Called from END MONTH (after rent, bills, construction): moods, move-outs, reputation, then 0-3 new tenant issues.
function tnMonth(){const T2=S.tn,mv=[];
 T2.q.forEach(it=>{if(!it.d){it.d=1;T2.nx.push(it)}else tnIgnore(gp(it.pid))});T2.q=[];
 S.props.filter(p=>p.tenant).forEach(p=>{const t=p.tenant;bump(t,p.late?-3:1,p.late?-2:1);if((t.hap<25&&Math.random()<.25)||(t.hap<40&&Math.random()<.08))mv.push(p)});
 mv.forEach(p=>tnLeave(p,'was unhappy with the property'));
 const rd=S.props.filter(p=>p.tenant),avg=rd.length?rd.reduce((a,p)=>a+p.tenant.hap,0)/rd.length:60;S.lr=cl(S.lr+(avg>=70?1:avg<40?-1:0));
 const list=[];rd.forEach(p=>{if(p.big||Math.random()<tnCh(p))list.push(mkIssue(p))});list.sort((a,b)=>(b.big?1:0)-(a.big?1:0));
 T2.q=T2.nx.filter(it=>{const p=gp(it.pid);return p&&p.tenant}).concat(list).slice(0,3);T2.nx=[]}
function issueNext(){const T2=S.tn;
 if(T2.news.length){modal(`<h2>📦 TENANT NEWS</h2>${T2.news.map(n=>`<p>${n}</p>`).join('')}<br><button class="btn" onclick="S.tn.news=[];save();issueNext()">OK</button>`);return}
 const it=T2.q[0];if(!it){closeModal();render();return}const p=gp(it.pid);if(!p||!p.tenant){T2.q.shift();return issueNext()}const t=p.tenant;
 modal(`<h2>📩 TENANT MESSAGE</h2><h3>${t.name} <span class="m">${t.pers} · ${p.n}</span></h3><div class="doc"><p>"${GR[t.pers]||GR.Friendly} ${it.big?'It got worse. ':''}${it.m}"</p></div>${kv('Issue',it.t)}${kv('Repair Cost',`<b>${R(it.c)}</b>`)}${kv('Happiness',`${mood(t)} ${t.hap}%`)}<div class="bar" style="margin:4px 0 8px"><i style="width:${t.hap}%;background:${hapCol(t.hap)}"></i></div><p class="m">Message 1 of ${T2.q.length}${it.d?' · already delayed once':''}</p><br><div class="row"><button class="btn gr" onclick="issueAct('fix')">FIX NOW</button>${it.d?'':`<button class="btn" onclick="issueAct('delay')">DELAY</button>`}<button class="btn rd" onclick="issueAct('ignore')">IGNORE</button></div>`)}
function issueAct(a){const T2=S.tn,it=T2.q[0];if(!it)return closeModal();const p=gp(it.pid),t=p&&p.tenant;
 if(a==='fix'){if(S.cash<it.c){snd(200,.25);return toast('Not enough cash to fix this now.','bad')}T2.q.shift();S.cash-=it.c;S.M.other+=it.c;tx(-it.c,'Repair: '+it.t,{k:'expense',prop:p?p.n:'',flat:p?p.flat:'',who:t?t.name:'',to:'Repair service',d:it.t+' repair'});if(t)bump(t,10,6);S.lr=cl(S.lr+2);coin();toast(`🔧 Fixed! ${t?t.name+' is happier.':''} -${R(it.c)}`,'good')}
 else if(a==='delay'&&!it.d){T2.q.shift();if(t)bump(t,-4,-1);it.d=1;T2.nx.push(it);toast('Delayed. The tenant will ask again next month.')}
 else{T2.q.shift();tnIgnore(p);snd(250,.2);toast('😠 Ignored. The tenant is upset.','bad');if(t&&Math.random()<Math.max(.05,(60-t.hap)/150))tnLeave(p,'frustrated by ignored repairs')}
 after();issueNext()}
function repCard(){const r=S.lr;return`<div class="card"><h3>⭐ LANDLORD REPUTATION</h3><div class="bar" style="margin:6px 0"><i style="width:${r}%"></i></div>${kv('Reputation',`${r}/100 · ${repLbl(r)}`)}<p class="m">Fix problems to earn trust: better tenants, contracts and rent. Ignoring them causes complaints and move-outs.</p></div>`}
function repHome(){const r=S.lr,q=S.tn.q.length;return`<div class="card"><h3>⭐ LANDLORD REPUTATION</h3><div class="bar" style="margin:6px 0"><i style="width:${r}%"></i></div>${kv('Reputation',`${r}/100 · ${repLbl(r)}`)}${q?`<br><button class="btn gr" onclick="issueNext()">📩 TENANT MESSAGES (${q})</button>`:''}</div>`}

/* ===== BUSINESS SYSTEM (inside Market): license, Real Estate Agency, Renovation Company, Management Company ===== */
let MT='prop',BM=0;
const sp=(t,c)=>`<span class="tag ${c||''}">${t}</span>`,bzF=id=>S.bz.list.find(b=>b.id===id),bzT=t=>S.bz.list.some(b=>b.type===t);
// ---- license ----
function bzChk(){const B=S.bz;if(!B.lic&&!B.offered&&nw()>=3000000){B.offered=true;B.pop=true}if(B.pop&&!B.lic&&$('#modal').hidden&&V!=='menu')bzOffer()}
function bzOffer(){modal(`<h2>🎉 YOU'RE READY FOR BUSINESS!</h2><p>You have reached ₹30,00,000. Your financial position qualifies you to become a business owner. Apply for your Business License.</p><br><div class="row"><button class="btn gr" onclick="bzApply()">GET BUSINESS LICENSE</button><button class="btn s" onclick="S.bz.pop=false;save();closeModal()">LATER</button></div>`)}
function bzApply(){const B=S.bz;if(B.lic||nw()<3000000){closeModal();return}B.lic={no:'BE-'+String(B.lno++).padStart(6,'0'),m:S.month};B.pop=false;coin();after();
 modal(`<h2>🎫 BUSINESS LICENSE APPROVED</h2><p>Welcome to the next stage of Property Empire. You can now purchase businesses.</p><br><div class="row"><button class="btn gr" onclick="MT='biz';BM=0;closeModal();go('market')">ENTER BUSINESS MARKET</button><button class="btn s" onclick="licMod()">VIEW BUSINESS CARD</button></div>`)}
function licMod(){const l=S.bz.lic;if(!l)return toast('You do not have a Business License yet. Reach ₹30,00,000 net worth.');modal(`<div class="lic"><small>PROPERTY EMPIRE</small><h2>BUSINESS LICENSE</h2>${kv('Business Owner','Player')}${kv('License No',l.no)}${kv('Status',`<b class="g">ACTIVE</b>`)}${kv('Capital Requirement','₹30,00,000')}${kv('Issued','Month '+l.m)}${kv('Business Access','APPROVED')}</div><br><button class="btn" onclick="closeModal()">CLOSE</button>`)}
// ---- shared helpers ----
const r1=n=>Math.round(n/1000)*1000;
const bzVal=b=>Math.round(b.price+b.inv*.8+(b.type==='reno'?(b.pr||[]).reduce((a,p)=>a+p.mv,0):0));
const mgUsed=b=>(b.cl||[]).reduce((a,c)=>a+c.u,0);
const bzMiss=t=>{const d=BIZ[t],w=nw(),n=S.props.length,m=[];if(w<d.nw)m.push('Net worth '+R(d.nw)+' (yours: '+R(w)+')');if(n<d.pr)m.push('Own '+d.pr+' of your own propert'+(d.pr===1?'y':'ies')+' (yours: '+n+')');return m};
// Business income: cash in, shown as business income and counted once in the monthly business profit.
function bzInc(b,a,label,m){S.cash+=a;S.M.biz+=a;S.M.cp+=a;b.prof+=a;b.mrev+=a;S.bz.st.profit+=a;tx(a,label,Object.assign({k:'bizinc',biz:b.name,gross:a,exp:0},m))}
// Business operating expenses: items=[{n,c}], one transaction per month. Returns the amount paid.
function bzExp(b,items){items=items.filter(i=>i.c>0);const c=items.reduce((a,i)=>a+i.c,0);if(!c)return 0;S.cash-=c;S.M.cp-=c;b.prof-=c;S.bz.st.profit-=c;tx(-c,b.name+' operating expenses',{k:'expense',biz:b.name,to:'Staff, office and suppliers',d:'Monthly operating expenses',items});return c}
// ---- buying ----
function bizBuyMod(t){const d=BIZ[t],short=d.p-S.cash;modal(`<h2>BUY ${d.n.toUpperCase()}?</h2>${kv('Price',R(d.p))}${kv('Your Cash',R(S.cash))}${kv('Savings',R(S.bank))}${kv('Cash After Purchase',`<b class="${short>0?'r':'g'}">${R(S.cash-d.p)}</b>`)}${short>0?`<p class="r">You need ${R(short)} more cash. Withdraw savings or take a bank loan in Finance. Savings are never used automatically.</p>`:''}<br><div class="row"><button class="btn s" onclick="closeModal()">CANCEL</button>${short>0?`<button class="btn" onclick="closeModal();go('fin')">OPEN FINANCE</button>`:`<button class="btn gr" onclick="buyBiz('${t}')">BUY</button>`}</div>`)}
function buyBiz(t){const d=BIZ[t],B=S.bz;if(!d||!B.lic||bzT(t)||S.cash<d.p||bzMiss(t).length){closeModal();return toast('Cannot buy this business right now.','bad')}
 const nm=d.nm[B.list.length%d.nm.length];S.cash-=d.p;tx(-d.p,'Business Purchased: '+d.n,{k:'bizbuy',biz:nm,d:d.n+' purchase'});
 const b={id:B.nid++,type:t,name:nm,price:d.p,m:S.month,inv:0,prof:0,mrev:0,lvl:1,last:{rev:0,exp:0,prof:0}};
 if(t==='agency'){Object.assign(b,{rep:10,deals:[],hist:[],dc:0});agNew(b)}
 if(t==='reno'){Object.assign(b,{mk:[],pr:[],hist:[],sold:0,win:0,jc:0});rnNew(b)}
 if(t==='mgmt'){Object.assign(b,{off:[],cl:[],ended:0});mgNew(b)}
 B.list.push(b);B.st.bought++;if(fDebt()>0)S.fin.pf=true;BM=b.id;coin();closeModal();after();pop(`🎉 ${d.ic} ${d.n.toUpperCase()} PURCHASED!`,`${b.name} is yours. Open it to get started.`)}
// ---- company upgrades (capital spending: not counted as income or expense, adds to business value) ----
function bzUpMod(id){const b=bzF(id);if(!b||b.lvl>=4)return;const c=UPC[b.type][b.lvl],short=c-S.cash;modal(`<h2>UPGRADE TO LEVEL ${b.lvl+1}?</h2><p>${UPN[b.type][b.lvl-1]}</p>${kv('Cost',R(c))}${kv('Your Cash',R(S.cash))}${short>0?`<p class="r">You need ${R(short)} more cash.</p>`:''}<br><div class="row"><button class="btn s" onclick="closeModal()">CANCEL</button><button class="btn gr" ${short>0?'disabled':''} onclick="bzUp(${id})">UPGRADE</button></div>`)}
function bzUp(id){const b=bzF(id);if(!b||b.lvl>=4)return closeModal();const c=UPC[b.type][b.lvl];if(S.cash<c){snd(200,.25);return toast('Not enough cash for this upgrade.','bad')}
 S.cash-=c;b.inv+=c;b.lvl++;tx(-c,b.name+' upgrade to level '+b.lvl,{k:'bizinv',biz:b.name,to:'Contractors and suppliers',d:UPN[b.type][b.lvl-2]});coin();closeModal();after();toast(`⬆️ ${b.name} is now level ${b.lvl}!`,'good')}
// ---- Real Estate Agency ----
function agNew(b){const n=AG.slots[b.lvl-1],mx=b.lvl-1,a=[];for(let i=0;i<n;i++){const r=Math.random(),t=Math.max(0,r<.5?mx:r<.8?mx-1:Math.floor(Math.random()*(mx+1))),v=r1(rnd(AG.rng[t][0],AG.rng[t][1]));
 a.push({id:S.bz.nid++,cl:pick(NAMES),pr:pick(AG.pr[t])+' in '+pick(AREAS),t,v,cm:Math.round(v*AG.rate[t]/100)*100,rq:AG.rq[t]})}b.deals=a}
function agDone(bid,did){const b=bzF(bid);if(!b)return;const d=b.deals.find(x=>x.id===did);
 if(!d||b.hist.some(h=>h.id===did))return toast('This deal was already completed.','bad');
 if(b.rep<d.rq)return toast('Locked: this deal needs reputation '+d.rq+'.','bad');
 b.deals=b.deals.filter(x=>x.id!==did);b.hist.unshift({id:did,m:S.month,cl:d.cl,pr:d.pr,v:d.v,cm:d.cm});if(b.hist.length>60)b.hist.length=60;b.dc++;b.rep=Math.min(100,b.rep+AG.gain);
 bzInc(b,d.cm,'Commission: '+d.pr,{src:'Sales commission',who:d.cl,d:`Sold ${d.pr} for ${R(d.v)}`});coin();after();toast(`💰 Deal closed! Commission ${R(d.cm)}`,'good')}
function agMonth(b){const exp=bzExp(b,[{n:'Office, agents & marketing',c:AG.ex[b.lvl-1]}]);b.last={rev:b.mrev,exp,prof:b.mrev-exp};b.mrev=0;agNew(b)}
// ---- Property Renovation Company ----
function rnNew(b){const cap=RN.cap[b.lvl-1],a=[];for(let i=0;i<3+b.lvl;i++){const V=r1(rnd(cap*.35,cap)),mv=r1(V*.78);a.push({id:S.bz.nid++,nm:pick(RN.pr)+' (needs work), '+pick(AREAS),V,mv,buy:r1(mv*rnd(.96,1.04))})}b.mk=a}
function rnBuy(bid,lid){const b=bzF(bid),l=b&&b.mk.find(x=>x.id===lid);if(!l)return toast('That listing is no longer available.','bad');
 if(b.pr.length>=RN.slots[b.lvl-1])return toast('Your company can only run '+RN.slots[b.lvl-1]+' projects at once. Sell one or upgrade.','bad');
 if(S.cash<l.buy){snd(200,.25);return toast('Not enough cash. Withdraw savings or take a loan in Finance.','bad')}
 S.cash-=l.buy;b.mk=b.mk.filter(x=>x.id!==lid);b.pr.push({id:l.id,nm:l.nm,V:l.V,buy:l.buy,mv:l.mv,reno:0,done:{},jobs:[],m:S.month});
 tx(-l.buy,'Renovation project bought: '+l.nm,{k:'bizinv',biz:b.name,prop:l.nm,to:'Property seller',d:'Property bought for renovation'});coin();after();toast('🔨 Property bought. Choose its renovations.','good')}
function rnJob(bid,pid,key){const b=bzF(bid),p=b&&b.pr.find(x=>x.id===pid),u=RNU.find(x=>x[0]===key);if(!p||!u)return;
 if(p.done[key]||p.jobs.some(j=>j.k===key))return toast('This renovation is already done or in progress.','bad');
 const c=r1(p.V*u[2]);if(S.cash<c){snd(200,.25);return toast('Not enough cash for this renovation. Withdraw savings or take a loan in Finance.','bad')}
 S.cash-=c;p.reno+=c;p.jobs.push({k:key,g:r1(p.V*u[3])});tx(-c,u[1]+': '+p.nm,{k:'bizinv',biz:b.name,prop:p.nm,to:'Renovation contractors',d:'Renovation: '+u[1]});coin();after();toast(`🛠️ ${u[1]} started. It finishes at month end.`,'good')}
const rnNet=p=>Math.round(p.mv*(1-RN.sc));
function rnSellMod(bid,pid){const b=bzF(bid),p=b&&b.pr.find(x=>x.id===pid);if(!p)return;if(p.jobs.length)return toast('Renovation work is still in progress. It finishes at month end.','bad');const net=rnNet(p),pf=net-p.buy-p.reno;
 modal(`<h2>SELL ${p.nm.toUpperCase()}?</h2>${kv('Estimated Market Value',R(p.mv))}${kv('Selling Cost ('+RN.sc*100+'%)',`<span class="r">-${R(p.mv-net)}</span>`)}${kv('Sale Proceeds',`<b>${R(net)}</b>`)}${kv('You Paid',R(p.buy))}${kv('Renovation Spent',R(p.reno))}${kv(pf>=0?'Profit':'Loss',`<b class="${pf>=0?'g':'r'}">${R(pf)}</b>`)}<br><div class="row"><button class="btn s" onclick="closeModal()">CANCEL</button><button class="btn gr" onclick="rnSell(${bid},${pid})">SELL</button></div>`)}
function rnSell(bid,pid){const b=bzF(bid),p=b&&b.pr.find(x=>x.id===pid);if(!p)return closeModal();if(p.jobs.length){closeModal();return toast('Renovation work is still in progress.','bad')}
 const net=rnNet(p),pf=net-p.buy-p.reno;b.pr=b.pr.filter(x=>x.id!==pid);S.cash+=net;
 tx(net,'Business property sold: '+p.nm,{k:'bizsale',biz:b.name,prop:p.nm,buy:p.buy,reno:p.reno,gross:p.mv,profit:pf,d:'Renovated property sold'});
 S.M.cp+=pf;if(pf>0)S.M.biz+=pf;b.prof+=pf;b.mrev+=pf;S.bz.st.profit+=pf;b.sold++;if(pf>0)b.win++;
 b.hist.unshift({id:p.id,m:S.month,nm:p.nm,buy:p.buy,reno:p.reno,sale:net,pf});if(b.hist.length>40)b.hist.length=40;coin();closeModal();after();
 pop(pf>=0?'💰 PROFITABLE SALE!':'📉 SOLD AT A LOSS',`${p.nm} sold for ${R(net)}. You paid ${R(p.buy)} and spent ${R(p.reno)} on renovations: ${pf>=0?'profit':'loss'} ${R(Math.abs(pf))}.`)}
function rnMonth(b){b.pr.forEach(p=>{if(p.jobs.length){p.jobs.forEach(j=>{p.mv+=j.g;p.done[j.k]=1;b.jc++});p.jobs=[];toast(`✅ Renovation finished at ${p.nm}`)}p.mv=Math.round(p.mv*(1+rnd(-.01,.015)))});
 const hold=b.pr.reduce((a,p)=>a+Math.round(p.buy*RN.hold),0),exp=bzExp(b,[{n:'Office & crew',c:RN.ex[b.lvl-1]},{n:'Holding costs (tax, security, upkeep)',c:hold}]);
 b.last={rev:b.mrev,exp,prof:b.mrev-exp};b.mrev=0;rnNew(b)}
// ---- Property Management Company (clients' properties are never added to S.props) ----
function mgNew(b){const a=[],mx=b.lvl-1;for(let i=0;i<3+(b.lvl>2?1:0);i++){const t=Math.random()<.6?mx:Math.floor(Math.random()*(mx+1));a.push({id:S.bz.nid++,ld:pick(LDN),u:Math.max(2,Math.round(rnd(2,4+b.lvl*2))),rt:r1(rnd(MG.rt[t][0],MG.rt[t][1])),fe:Math.round(rnd(9,12.49))/100,ar:pick(AREAS),left:12})}b.off=a}
function mgAccept(bid,oid){const b=bzF(bid),o=b&&b.off.find(x=>x.id===oid);if(!o)return toast('That offer has expired.','bad');
 if(mgUsed(b)+o.u>MG.cap[b.lvl-1]){snd(200,.25);return toast('Not enough capacity. Upgrade your company to manage more units.','bad')}
 b.off=b.off.filter(x=>x.id!==oid);b.cl.push(Object.assign({},o,{since:S.month}));coin();after();toast(`📝 Contract signed with ${o.ld}`,'good')}
const mgFee=c=>Math.round(c.u*c.rt*c.fe);
function mgMonth(b){const used=mgUsed(b);let fees=0;b.cl.forEach(c=>{fees+=Math.round(mgFee(c)*rnd(.92,1))});
 if(fees>0)bzInc(b,fees,b.name+' management fees',{src:'Management fees',who:b.cl.length+' client landlord'+(b.cl.length===1?'':'s'),d:`Monthly fees for ${used} managed units`});
 const exp=bzExp(b,[{n:'Office & managers',c:MG.ex[b.lvl-1]},{n:'Maintenance team ('+used+' units)',c:used*MG.per}]);
 b.cl=b.cl.filter(c=>{if(--c.left>0)return true;if(Math.random()<.8){c.left=12;toast(`🔁 ${c.ld} renewed the management contract.`);return true}b.ended++;toast(`📄 ${c.ld} did not renew the contract.`);return false});
 b.last={rev:b.mrev,exp,prof:b.mrev-exp};b.mrev=0;mgNew(b)}
// ---- monthly processing (called at the start of endMonth) ----
function bzMonth(){const B=S.bz;B.list.forEach(b=>{if(b.type==='agency')agMonth(b);else if(b.type==='reno')rnMonth(b);else if(b.type==='mgmt')mgMonth(b)});
 if(S.fin.borrowed>0&&B.list.length&&fDebt()<=loanLimit()/2)S.fin.rd=true}
// ---- screens ----
function bzHome(){const B=S.bz,w=nw();if(!B.lic)return`<div class="card"><h3>🏢 BUSINESS</h3><p class="m">Reach ₹30,00,000 net worth to unlock the Business Market.</p><div class="bar" style="margin:6px 0"><i style="width:${Math.max(0,Math.min(100,w/30000))}%"></i></div>${kv('Net Worth',R(w))}</div>`;
 const pf=B.list.reduce((a,b)=>a+b.last.prof,0);return`<div class="card"><h3>🏢 BUSINESS</h3>${kv('Businesses',B.list.length)}${kv('Last Month Profit',`<span class="${pf>=0?'g':'r'}">${R(pf)}</span>`)}<br><button class="btn s" onclick="MT='biz';BM=0;go('market')">OPEN BUSINESS MARKET</button></div>`}
function marketView(){return`<h2>🏪 Market</h2><div class="pills" style="margin-bottom:10px"><button class="${MT==='prop'?'on':''}" onclick="MT='prop';BM=0;render()">🏠 PROPERTY</button><button class="${MT==='biz'?'on':''}" onclick="MT='biz';render()">🏢 BUSINESS</button></div>`+(MT==='prop'?views.marketOld():bzMarket())}
function bzMarket(){const B=S.bz,w=nw(),lv=bLvl();
 let h=`<div class="card"><h3>🏢 BUSINESS MARKET</h3>${kv('Business Level',sp(BLN[lv-1],'g'))}${kv('Net Worth',R(w))}</div>`;
 if(!B.lic)return h+`<div class="card"><h3>🔒 BUSINESS LICENSE REQUIRED</h3><p>Reach ₹30,00,000 net worth to apply for a Business License.</p><div class="bar" style="margin:8px 0"><i style="width:${Math.max(0,Math.min(100,w/30000))}%"></i></div>${kv('Progress',R(w)+' / ₹30,00,000')}${w>=3000000?'<br><button class="btn gr" onclick="bzApply()">APPLY FOR LICENSE</button>':''}</div>`;
 if(BM&&bzF(BM))return bzManage(bzF(BM));
 h+=`<button class="btn s" onclick="licMod()">📄 VIEW BUSINESS LICENSE</button><br><br>`+Object.keys(BIZ).map(k=>{const d=BIZ[k],m=bzMiss(k),own=bzF(S.bz.list.find(b=>b.type===k)?.id);
  return`<div class="card"><h3>${d.ic} ${d.n.toUpperCase()}</h3>${kv('Price',`<b>${R(d.p)}</b>`)}${kv('Unlock',d.nw?'Net worth '+R(d.nw)+(d.pr?' · '+d.pr+' properties':''):'Business License')}<p class="m">${DESC[k]}</p><br>${own?`${sp('✅ Owned','g')} <button class="btn sm gr" style="margin-left:8px" onclick="BM=${own.id};render()">MANAGE</button>`:m.length?`<p class="r">🔒 ${m.join(' · ')}</p>`:`<button class="btn ${S.cash>=d.p?'gr':'s'}" onclick="bizBuyMod('${k}')">BUY ${R(d.p)}</button>`}</div>`}).join('');
 return h+(B.list.length?'<h2>MY BUSINESSES</h2>'+B.list.map(bzCard).join(''):'')}
function bzCard(b){const d=BIZ[b.type],L=b.last;let rows='';
 if(b.type==='agency')rows=kv('Reputation','⭐ '+b.rep+'/100')+kv('Deals Completed',b.dc)+kv('Open Deals',b.deals.length);
 if(b.type==='reno')rows=kv('Projects',b.pr.length+'/'+RN.slots[b.lvl-1])+kv('Properties Sold',b.sold);
 if(b.type==='mgmt')rows=kv('Managed Units',mgUsed(b)+'/'+MG.cap[b.lvl-1])+kv('Client Contracts',b.cl.length);
 return`<div class="card"><h3>${d.ic} ${b.name}</h3>${kv('Level',b.lvl+' · '+BZLV[b.lvl-1])}${kv('Value',R(bzVal(b)))}${rows}${kv('Last Month Profit',`<b class="${L.prof>=0?'g':'r'}">${R(L.prof)}</b>`)}<br><button class="btn gr" onclick="BM=${b.id};render()">MANAGE</button></div>`}
function bzUpCard(b){if(b.lvl>=4)return`<div class="card"><h3>⬆️ COMPANY LEVEL</h3><span class="tag g">Maximum level reached ✅</span></div>`;const c=UPC[b.type][b.lvl];
 const nx={agency:`Level ${b.lvl+1}: ${AG.slots[b.lvl]} deals per month, bigger deals (up to ${R(AG.rng[b.lvl][1])}). Expenses rise to ${R(AG.ex[b.lvl])}/month.`,reno:`Level ${b.lvl+1}: ${RN.slots[b.lvl]} projects at once, properties up to ${R(RN.cap[b.lvl])}. Office cost rises to ${R(RN.ex[b.lvl])}/month.`,mgmt:`Level ${b.lvl+1}: manage up to ${MG.cap[b.lvl]} units. Office cost rises to ${R(MG.ex[b.lvl])}/month.`}[b.type];
 return`<div class="card"><h3>⬆️ UPGRADE: ${UPN[b.type][b.lvl-1]}</h3><p class="m">${nx}</p>${kv('Cost',`<b>${R(c)}</b>`)}<br><button class="btn ${S.cash>=c?'gr':'s'}" onclick="bzUpMod(${b.id})">UPGRADE ${R(c)}</button></div>`}
function bzManage(b){const d=BIZ[b.type],L=b.last,hd=`<button class="btn s sm" onclick="BM=0;render()">⬅ All businesses</button><br><br>`;
 let top=`<div class="card"><h3>${d.ic} ${b.name}</h3>${kv('Level',b.lvl+' · '+BZLV[b.lvl-1])}${kv('Business Value',R(bzVal(b)))}${kv('Last Month Revenue',`<span class="g">${R(L.rev)}</span>`)}${kv('Last Month Expenses',`<span class="r">${R(L.exp)}</span>`)}${kv('Last Month Profit',`<b class="${L.prof>=0?'g':'r'}">${R(L.prof)}</b>`)}${kv('Total Profit So Far',`<b class="${b.prof>=0?'g':'r'}">${R(b.prof)}</b>`)}`;
 if(b.type==='agency')return hd+top+`${kv('Monthly Operating Expenses',`<span class="r">${R(AG.ex[b.lvl-1])}</span>`)}${kv('Earned This Month',R(b.mrev))}${kv('Reputation','⭐ '+b.rep+'/100')}<div class="bar" style="margin:6px 0"><i style="width:${b.rep}%"></i></div>${kv('Deals Completed',b.dc)}<p class="m">Expenses are paid at the end of every month. New deals arrive each month; unfinished deals expire.</p></div>`+bzUpCard(b)+agDeals(b);
 if(b.type==='reno')return hd+top+`${kv('Monthly Office Cost',`<span class="r">${R(RN.ex[b.lvl-1])}</span>`)}${kv('Projects',b.pr.length+'/'+RN.slots[b.lvl-1])}${kv('Properties Sold',b.sold+' ('+b.win+' profitable)')}<p class="m">Profit or loss is recorded when you sell. Renovations finish at month end. These properties belong to your company, not to My Properties.</p></div>`+bzUpCard(b)+rnView(b);
 const used=mgUsed(b),cap=MG.cap[b.lvl-1],inc=b.cl.reduce((a,c)=>a+mgFee(c),0),ex=MG.ex[b.lvl-1]+used*MG.per;
 return hd+top+`${kv('Managed Units',used+'/'+cap)}<div class="bar" style="margin:6px 0"><i style="width:${cap?used/cap*100:0}%"></i></div>${kv('Client Contracts',b.cl.length)}${kv('Expected Monthly Fees',`<span class="g">${R(inc)}</span>`)}${kv('Monthly Operating Expenses',`<span class="r">${R(ex)}</span>`)}${kv('Expected Monthly Profit',`<b class="${inc-ex>=0?'g':'r'}">${R(inc-ex)}</b>`)}<p class="m">Managed units belong to your clients and are never added to your own properties.</p></div>`+bzUpCard(b)+mgView(b)}
function agDeals(b){const h=`<h2>📋 DEALS THIS MONTH</h2>`;return h+(b.deals.length?b.deals.map(d=>{const lock=b.rep<d.rq;return`<div class="card obj"><h3>${d.pr}</h3>${kv('Client',d.cl)}${kv('Sale Price',R(d.v))}${kv('Commission ('+(AG.rate[d.t]*100).toFixed(1)+'%)',`<b class="g">${R(d.cm)}</b>`)}${lock?`<p class="r">🔒 Needs reputation ${d.rq} (yours: ${b.rep})</p>`:`<button class="btn gr" onclick="agDone(${b.id},${d.id})">COMPLETE DEAL</button>`}</div>`}).join(''):'<div class="card">No open deals. New deals arrive next month.</div>')+`<h2>🗂️ DEAL HISTORY</h2>`+(b.hist.length?b.hist.slice(0,20).map(x=>`<div class="card"><div class="kv"><b>${x.pr}</b><b class="g">+${R(x.cm)}</b></div><p class="m">${x.cl} · sold for ${R(x.v)} · Month ${x.m}</p></div>`).join(''):'<div class="card">No deals completed yet.</div>')}
function rnView(b){let h=`<h2>🛠️ MY PROJECTS</h2>`;
 h+=b.pr.length?b.pr.map(p=>{const net=rnNet(p),pf=net-p.buy-p.reno;return`<div class="card"><h3>${p.nm}</h3>${kv('Purchase Price',R(p.buy))}${kv('Renovation Spent',R(p.reno))}${kv('Estimated Market Value',`<b>${R(p.mv)}</b>`)}${kv('If Sold Now',`<b class="${pf>=0?'g':'r'}">${pf>=0?'Profit':'Loss'} ${R(Math.abs(pf))}</b>`)}<h3 style="margin-top:8px">Renovations</h3>${RNU.map(u=>{const c=r1(p.V*u[2]),g=r1(p.V*u[3]),st=p.done[u[0]]?'<span class="tag g">Done ✅</span>':p.jobs.some(j=>j.k===u[0])?'<span class="tag">In progress ⏳</span>':`<button class="btn sm ${S.cash>=c?'gr':'s'}" onclick="rnJob(${b.id},${p.id},'${u[0]}')">${R(c)}</button>`;return`<div class="kv"><span>${u[1]}<small class="m"><br>+${R(g)} value</small></span>${st}</div>`}).join('')}<br><button class="btn ${p.jobs.length?'s':'gr'}" onclick="rnSellMod(${b.id},${p.id})">${p.jobs.length?'WORK IN PROGRESS':'SELL PROPERTY'}</button></div>`}).join(''):'<div class="card">No projects yet. Buy a property below.</div>';
 h+=`<h2>🏚️ PROPERTIES FOR SALE</h2><p class="m">Eligible up to ${R(RN.cap[b.lvl-1])} renovated value. New listings arrive each month.</p>`;
 h+=b.mk.length?b.mk.map(l=>`<div class="card obj"><h3>${l.nm}</h3>${kv('Price',`<b>${R(l.buy)}</b>`)}${kv('Estimated Value Today',R(l.mv))}<button class="btn ${S.cash>=l.buy&&b.pr.length<RN.slots[b.lvl-1]?'gr':'s'}" onclick="rnBuy(${b.id},${l.id})">BUY ${R(l.buy)}</button></div>`).join(''):'<div class="card">No listings right now.</div>';
 return h+`<h2>🧾 SALES HISTORY</h2>`+(b.hist.length?b.hist.slice(0,15).map(x=>`<div class="card"><div class="kv"><b>${x.nm}</b><b class="${x.pf>=0?'g':'r'}">${x.pf>=0?'+':'−'}${R(Math.abs(x.pf))}</b></div><p class="m">Bought ${R(x.buy)} · Renovated ${R(x.reno)} · Sold ${R(x.sale)} · Month ${x.m}</p></div>`).join(''):'<div class="card">No properties sold yet.</div>')}
function mgView(b){const cap=MG.cap[b.lvl-1],used=mgUsed(b);let h=`<h2>📝 CLIENT OFFERS</h2>`;
 h+=b.off.length?b.off.map(o=>{const fit=used+o.u<=cap;return`<div class="card obj"><h3>${o.ld}</h3>${kv('Properties',o.u+' units in '+o.ar)}${kv('Average Rent',R(o.rt)+'/unit')}${kv('Management Fee',(o.fe*100).toFixed(0)+'%')}${kv('Monthly Fee',`<b class="g">${R(mgFee(o))}</b>`)}${kv('Contract','12 months')}${fit?`<button class="btn gr" onclick="mgAccept(${b.id},${o.id})">SIGN CONTRACT</button>`:`<p class="r">🔒 Needs ${used+o.u-cap} more unit capacity. Upgrade your company.</p>`}</div>`}).join(''):'<div class="card">No client offers right now. New offers arrive next month.</div>';
 h+=`<h2>🗂️ ACTIVE CONTRACTS</h2>`;
 h+=b.cl.length?b.cl.map(c=>`<div class="card"><div class="kv"><b>${c.ld}</b><b class="g">${R(mgFee(c))}/month</b></div><p class="m">${c.u} units in ${c.ar} · ${R(c.rt)}/unit · ${(c.fe*100).toFixed(0)}% fee · ${c.left} month${c.left===1?'':'s'} left</p></div>`).join(''):'<div class="card">No active contracts yet.</div>';
 return h+`<p class="m">Contracts ended or not renewed so far: ${b.ended}</p>`}

/* ===== RENT PAYMENT RECEIPT ===== */
let RC=null;
function rcpt(p,prev,amt){const rc=S.rc,t=p.tenant,r={no:'RENT-'+String(++rc.n).padStart(6,'0'),m:S.month,tn:t.name,job:t.job,pers:t.pers,prop:p.n,flat:p.flat,rent:p.rent,amt,prev,cur:S.cash};rc.list.unshift(r);if(rc.list.length>50)rc.list.length=50;const rec=S.fin.tx.find(z=>z.k==='rent'&&!z.rc&&z.x.pid===p.id&&z.a===amt);if(rec){rec.rc=r.no;r.tid=rec.id}save();rcView(r)}
function rcView(r){const extra=r.amt>r.rent?r.amt-r.rent:0,main=extra?r.rent:r.amt;
 modal(`<div class="rcpt"><div class="rc-h"><small>PROPERTY EMPIRE</small><h2>Rent Payment Receipt</h2></div><div class="rc-m"><span>Date: Month ${r.m}</span><span>Receipt #: ${r.no}</span>${r.tid?`<span>Transaction: ${r.tid}</span>`:''}</div>
 <p class="rc-q"><b>${r.tn}:</b> "${GR[r.pers]||GR.Friendly} I've transferred this month's rent."</p>
 <div class="rc-s">PAID BY</div><div><b>${r.tn}</b> · ${r.job}</div>
 <div class="rc-g"><div><small>PROPERTY</small>${r.prop}</div><div><small>UNIT</small>Flat ${r.flat}</div><div><small>TENANT</small>${r.tn}</div><div><small>MONTH</small>Month ${r.m}</div><div><small>RENT</small>${R(r.rent)}</div></div>
 <div class="rc-r"><small>DESCRIPTION</small><small>AMOUNT</small></div><div class="rc-r"><span>${extra?'Monthly Rent':'Rent Payment'}</span><b>${R(main)}</b></div>${extra?`<div class="rc-r"><span>Overdue Rent Recovered</span><b>${R(extra)}</b></div>`:''}
 <div class="rc-t"><span>TOTAL RECEIVED</span><b>${R(r.amt)}</b></div><div class="rc-ok">✓ PAYMENT RECEIVED</div>
 <div class="rc-r"><span>Previous Cash</span><b>${R(r.prev)}</b></div><div class="rc-r"><span>Rent Received</span><b class="g">+${R(r.amt)}</b></div><div class="rc-r"><span>Current Cash</span><b>${R(r.cur)}</b></div>
 <p class="rc-th">Rent payment received successfully.<br>Thank you for maintaining your property with Property Empire.</p><button class="btn" onclick="closeModal()">CLOSE</button></div>`)}
function rcList(){const l=S.rc.list;return l.length?`<div class="card"><h3>🧾 RENT RECEIPTS</h3><p class="m">Your latest ${l.length} receipts.</p></div>`+l.map((r,i)=>`<div class="card"><h3>${r.no}</h3>${kv('Tenant',r.tn)}${kv('Property',r.prop+' — Flat '+r.flat)}${kv('Amount',`<b class="g">${R(r.amt)}</b>`)}${kv('Month','Month '+r.m)}<br><button class="btn s" onclick="rcView(S.rc.list[${i}])">VIEW RECEIPT</button></div>`).join(''):'<div class="card">No rent receipts yet. Collect rent to receive one.</div>'}

/* ===== MY LIFE: overview, vehicles, art, travel, lifestyle, personal expenses, documents ===== */
let LT='ov',VT='car',EF='all',TP=null;
const nid=()=>S.life.next++,PAL=['#e8a317','#3b82c4','#d6453d','#2e8b73','#8a5cc2','#13322f'];
const carSvg=(c,v)=>{const h=[1,1,1.2,.78,.68][v];return`<svg viewBox="0 0 120 60" class="ill"><ellipse cx="60" cy="52" rx="48" ry="3" fill="#0002"/><g transform="translate(0 ${40*(1-h)}) scale(1 ${h})"><path d="M8 40 Q10 28 28 26 L44 14 H80 L98 26 Q114 28 114 40 Z" fill="${c}"/><path d="M48 17 H78 L92 26 H40 Z" fill="#cfe8ff"/></g><circle cx="32" cy="42" r="8" fill="#13322f"/><circle cx="92" cy="42" r="8" fill="#13322f"/><circle cx="32" cy="42" r="3" fill="#ddd"/><circle cx="92" cy="42" r="3" fill="#ddd"/></svg>`};
const boatSvg=(c,v)=>`<svg viewBox="0 0 120 60" class="ill"><path d="M8 36 H112 L98 50 H22 Z" fill="${c}"/><rect x="46" y="22" width="34" height="14" rx="3" fill="#fff"/>${v>0?'<rect x="54" y="12" width="22" height="10" rx="3" fill="#cfe8ff"/>':''}${v>1?'<rect x="28" y="28" width="14" height="8" fill="#fff"/><rect x="84" y="28" width="14" height="8" fill="#fff"/>':''}<path d="M0 55 Q15 51 30 55 T60 55 T90 55 T120 55" fill="none" stroke="#3b82c4" stroke-width="2"/></svg>`;
const planeSvg=(c,v)=>`<svg viewBox="0 0 120 60" class="ill"><ellipse cx="60" cy="30" rx="${42+v*4}" ry="7" fill="${c}"/><polygon points="55,30 38,${52-v*4} 54,${52-v*4} 74,30" fill="${c}" opacity=".85"/><polygon points="98,30 106,${14-v*2} 113,${14-v*2} 110,30" fill="${c}"/><g fill="#cfe8ff"><circle cx="36" cy="29" r="1.8"/><circle cx="44" cy="29" r="1.8"/><circle cx="52" cy="29" r="1.8"/><circle cx="60" cy="29" r="1.8"/></g></svg>`;
const houseSvg=v=>`<svg viewBox="0 0 120 60" class="ill"><rect x="${22-v*2}" y="${30-v*5}" width="${76+v*4}" height="${24+v*5}" fill="#fff8e1" stroke="#13322f" stroke-width="2"/><polygon points="${18-v*2},${30-v*5} 60,${8-v*3} ${102+v*2},${30-v*5}" fill="${['#2e8b73','#d6453d','#3b82c4','#8a5cc2'][v]}"/><g fill="#e8a317"><rect x="34" y="36" width="12" height="10"/><rect x="74" y="36" width="12" height="10"/></g><rect x="55" y="40" width="10" height="14" fill="#13322f"/></svg>`;
const CARIMG={hatch:'city_hatchback',sedan:'family_sedan',suv:'luxury_suv',sport:'sports_car',super:'supercar'};
function carFail(el,k){console.warn('[Property Empire] Vehicle image failed to load for '+k+' - showing a fallback illustration.');const d=LF(k);el.outerHTML=d.t==='boat'?boatSvg(d.c,d.v):d.t==='plane'?planeSvg(d.c,d.v):carSvg(d.c,d.v)}
const CARD={hatch:"data:image/webp;base64,",sedan:"data:image/webp;base64,",suv:"data:image/webp;base64,",sport:"data:image/webp;base64,",super:"data:image/webp;base64,",moto:"data:image/webp;base64,",speed:"data:image/webp;base64,",yacht:"data:image/webp;base64,",small:"data:image/webp;base64,",jet:"data:image/webp;base64,",ljet:"data:image/webp;base64,"};
const VDARK=[]; // new vehicle images are truly transparent, no dark tile needed
const carImg=d=>`<img class="carimg${VDARK.includes(d.k)?' dk':''}" src="${CARD[d.k]||'assets/cars/'+CARIMG[d.k]+'.png'}" alt="${d.n}" loading="lazy" onerror="carFail(this,'${d.k}')">`;
// Art Collection (10) and Personal Homes (4) pictures, keyed by their file names. Embedded WebP data URLs, no external files.
const IMGS={modern_landscape_painting:"data:image/webp;base64,",harbour_sunrise_canvas:"data:image/webp;base64,",marble_sculpture:"data:image/webp;base64,",bronze_figure:"data:image/webp;base64,",abstract_masterpiece:"data:image/webp;base64,",geometric_series:"data:image/webp;base64,",luxury_gallery_artwork:"data:image/webp;base64,",gilded_mirror_panel:"data:image/webp;base64,",rare_collectible:"data:image/webp;base64,",antique_chronometer:"data:image/webp;base64,",city_studio:"data:image/webp;base64,",family_villa:"data:image/webp;base64,",beach_house:"data:image/webp;base64,",skyline_penthouse:"data:image/webp;base64,"};
const ARTF={land:'modern_landscape_painting',harb:'harbour_sunrise_canvas',marb:'marble_sculpture',bron:'bronze_figure',abst:'abstract_masterpiece',geo:'geometric_series',gall:'luxury_gallery_artwork',mirr:'gilded_mirror_panel',rare:'rare_collectible',chron:'antique_chronometer'},HOMEF={studio:'city_studio',villa:'family_villa',beach:'beach_house',pent:'skyline_penthouse'};
function pFail(el,kind,k){console.warn('[Property Empire] Image failed to load for '+kind+' '+k+' - showing a fallback illustration.');if(kind==='art'){const a=ARTS.find(x=>x.k===k);el.outerHTML=artSvg(a.cat,a.i)}else{const h=LF(k);el.outerHTML=houseSvg(h.v)}}
const pImg=(name,alt,kind,k)=>`<img class="pimg" src="${IMGS[name]}" alt="${alt}" loading="lazy" onerror="pFail(this,'${kind}','${k}')">`;
const artPic=d=>IMGS[ARTF[d.k]]?pImg(ARTF[d.k],d.n,'art',d.k):artSvg(d.cat,d.i);
const svgOf=d=>CARD[d.k]?carImg(d):d.t==='home'&&IMGS[HOMEF[d.k]]?pImg(HOMEF[d.k],d.n,'home',d.k):d.t==='car'?carSvg(d.c,d.v):d.t==='boat'?boatSvg(d.c,d.v):d.t==='plane'?planeSvg(d.c,d.v):houseSvg(d.v);
const artSvg=(cat,i)=>{const a=PAL[i%6],b=PAL[(i+2)%6],bg='<rect width="120" height="60" fill="#fffdf4"/>';return`<svg viewBox="0 0 120 60" class="ill">${cat==='Paintings'?`<rect width="120" height="60" fill="#cfe8ff"/><circle cx="90" cy="16" r="9" fill="${a}"/><path d="M0 60 L0 40 Q30 22 60 40 T120 36 L120 60Z" fill="${b}"/>`:cat==='Sculptures'?`${bg}<rect x="42" y="46" width="36" height="9" fill="#bbb"/><circle cx="60" cy="16" r="8" fill="#ddd"/><path d="M50 24 H70 L74 46 H46Z" fill="#ccc"/>`:cat==='Modern Art'?`${bg}<rect x="14" y="10" width="34" height="38" fill="${a}"/><circle cx="72" cy="30" r="18" fill="${b}"/><polygon points="90,52 104,14 114,52" fill="#13322f"/>`:cat==='Luxury Decorative Art'?`${bg}<rect x="12" y="6" width="96" height="48" fill="none" stroke="#c9a227" stroke-width="5"/><circle cx="60" cy="30" r="14" fill="none" stroke="${a}" stroke-width="4"/><circle cx="60" cy="30" r="5" fill="#c9a227"/>`:`${bg}<polygon points="60,6 86,22 60,54 34,22" fill="${a}"/><polygon points="60,6 72,22 60,54 48,22" fill="#fff6" /><line x1="34" y1="22" x2="86" y2="22" stroke="#fff" stroke-width="2"/>`}</svg>`};
const age=m=>Math.max(0,S.month-(m||S.month));
function vVal(it){const d=LF(it.k),a=age(it.m);if(d.t==='home')return Math.round(it.pp*Math.min(1.3,1+.003*a)/1000)*1000;const r=d.t==='car'?[.008,.5]:d.t==='boat'?[.006,.55]:[.004,.6];return Math.round(it.pp*Math.max(r[1],1-r[0]*a)/1000)*1000}
const lifeAssets=()=>S.life.own.reduce((a,o)=>a+vVal(o),0)+S.life.art.reduce((a,o)=>a+o.val,0);
const NOFUND='Not enough cash. Withdraw savings or take a bank loan in Finance.';
// lspend = personal spending (expense); abuy = asset purchase (counted in assets, not spending). Both only act when cash covers it.
function lspend(c,cat,d,m){if(S.cash<c){snd(200,.25);toast(NOFUND,'bad');return null}S.cash-=c;S.life.spent+=c;return tx(-c,d,Object.assign({k:'life',cat,d},m))}
function abuy(c,cat,d,m){if(S.cash<c){snd(200,.25);toast(NOFUND,'bad');return null}S.cash-=c;return tx(-c,d,Object.assign({k:'asset',cat,d},m))}
function asell(v,cat,d,m){S.cash+=v;return tx(v,d,Object.assign({k:'asset',cat,d},m))}
// ---- vehicles & homes ----
function vMod(k){const d=LF(k),own=S.life.own.some(o=>o.k===k);modal(`<h2>${d.n}</h2>${svgOf(d)}${kv('Purchase Price',R(d.p))}${kv('Monthly Maintenance',R(d.u))}${kv('Estimated Value After Purchase',R(d.p))}${kv('Your Cash',R(S.cash))}${kv('Cash After Purchase',`<b class="${S.cash>=d.p?'g':'r'}">${R(S.cash-d.p)}</b>`)}<p class="m">Paid from cash only. Savings are never used automatically. ${d.t==='home'?'Homes slowly gain value.':'Vehicles lose value over time.'} It earns no income.</p><br><div class="row"><button class="btn s" onclick="closeModal()">CLOSE</button>${own?'':`<button class="btn gr" onclick="vBuy('${k}')">BUY ${R(d.p)}</button>`}</div>`)}
function vBuy(k){const d=LF(k);if(S.life.own.some(o=>o.k===k))return closeModal();if(!abuy(d.p,d.t==='home'?'Homes':'Vehicles','Bought '+d.n,{item:d.n,pp:d.p}))return;S.life.own.push({id:nid(),k,pp:d.p,m:S.month,mm:S.month-1});coin();closeModal();after();pop(`🎉 ${d.n.toUpperCase()} PURCHASED!`,`Monthly maintenance: ${R(d.u)}. Its value is tracked as an asset.`)}
function vSellMod(id){const it=S.life.own.find(o=>o.id===id),d=LF(it.k),v=vVal(it);modal(`<h2>SELL ${d.n.toUpperCase()}?</h2>${kv('Purchase Price',R(it.pp))}${kv('Estimated Value',R(v))}${kv('Gain / Loss',`<b class="${v>=it.pp?'g':'r'}">${v>=it.pp?'+':'−'}${R(Math.abs(v-it.pp))}</b>`)}<br><div class="row"><button class="btn s" onclick="closeModal()">CANCEL</button><button class="btn gr" onclick="vSell(${id})">SELL FOR ${R(v)}</button></div>`)}
function vSell(id){const it=S.life.own.find(o=>o.id===id);if(!it)return closeModal();const d=LF(it.k),v=vVal(it);asell(v,d.t==='home'?'Homes':'Vehicles','Sold '+d.n,{item:d.n,pp:it.pp});S.life.own=S.life.own.filter(o=>o.id!==id);coin();closeModal();after();toast(`Sold ${d.n} for ${R(v)}`,'good')}
function vPay(id){const it=S.life.own.find(o=>o.id===id),d=LF(it.k);if((it.mm||0)>=S.month)return toast('Maintenance is already paid for this month.');if(!lspend(d.u,'Maintenance',d.n+' maintenance',{to:'Service provider',items:[{n:d.n,c:d.u}]}))return;it.mm=S.month;S.M.lm+=d.u;S.M.other+=d.u;coin();after();toast(`Maintenance paid: ${R(d.u)}`,'good')}
// ---- art ----
const artist=i=>ARTISTS[i%ARTISTS.length];
function aMod(k){const d=ARTS.find(x=>x.k===k);modal(`<h2>${d.n}</h2>${artPic(d)}${kv('Style',d.st)}${kv('Artist',artist(d.i))}${kv('Purchase Price',R(d.p))}${kv('Your Cash',R(S.cash))}${kv('Cash After Purchase',`<b class="${S.cash>=d.p?'g':'r'}">${R(S.cash-d.p)}</b>`)}<p class="m">Value can rise or fall over time. It is tracked as an asset.</p><br><div class="row"><button class="btn s" onclick="closeModal()">CANCEL</button><button class="btn gr" onclick="aBuy('${k}')">BUY ${R(d.p)}</button></div>`)}
function aBuy(k){const d=ARTS.find(x=>x.k===k);if(S.life.art.some(a=>a.k===k))return closeModal();if(!abuy(d.p,'Art','Bought '+d.n,{item:d.n,pp:d.p}))return;S.life.art.push({id:nid(),k,pp:d.p,val:d.p,m:S.month});coin();closeModal();after();pop('🖼️ ARTWORK ACQUIRED!',`${d.n} by ${artist(d.i)} joins your collection.`)}
function aSellMod(id){const a=S.life.art.find(x=>x.id===id),d=ARTS.find(x=>x.k===a.k);modal(`<h2>SELL ${d.n.toUpperCase()}?</h2>${kv('Purchase Price',R(a.pp))}${kv('Estimated Value',R(a.val))}${kv('Gain / Loss',`<b class="${a.val>=a.pp?'g':'r'}">${a.val>=a.pp?'+':'−'}${R(Math.abs(a.val-a.pp))}</b>`)}<br><div class="row"><button class="btn s" onclick="closeModal()">CANCEL</button><button class="btn gr" onclick="aSell(${id})">SELL FOR ${R(a.val)}</button></div>`)}
function aSell(id){const a=S.life.art.find(x=>x.id===id);if(!a)return closeModal();const d=ARTS.find(x=>x.k===a.k);asell(a.val,'Art','Sold '+d.n,{item:d.n,pp:a.pp});S.life.art=S.life.art.filter(x=>x.id!==id);coin();closeModal();after();toast(`Sold ${d.n} for ${R(a.val)}`,'good')}
// ---- monthly: vehicle/home maintenance (once per month per item) + art value changes ----
function lifeMonth(){const L=S.life,items=[];let tot=0;L.own.forEach(it=>{const d=LF(it.k);if(d.n==='?'||(it.mm||0)>=S.month)return;it.mm=S.month;tot+=d.u;items.push({n:d.n+' maintenance',c:d.u})});
 if(tot){S.cash-=tot;L.spent+=tot;S.M.lm+=tot;tx(-tot,'Monthly maintenance',{k:'life',cat:'Maintenance',d:'Monthly maintenance of vehicles and homes',to:'Service providers',items})}
 L.art.forEach(a=>{if(Math.random()<.12)a.val=Math.round(Math.max(a.pp*.4,Math.min(a.pp*3,a.val*(1+pick([-.1,-.05,.04,.08,.12]))))/100)*100});return tot}
// ---- travel & activities ----
const dstCost=(d,days,sel)=>{const fl=Math.round(d.fl*(hasPlane()?.75:1)),ho=d.ho*days,fo=d.fo*days,acts=sel.reduce((a,i)=>a+d.v[i][1],0);return{fl,ho,fo,acts,total:fl+ho+fo+acts}};
function tpMod(k){if(k)TP={k,days:3,sel:[]};const d=DEST.find(x=>x.k===TP.k),c=dstCost(d,TP.days,TP.sel),ok=S.cash>=c.total;
 modal(`<h2>${d.f} ${d.city}, ${d.co}</h2><p class="m">${d.ds}</p><br><div class="row">${[2,3,5,7].map(n=>`<button class="btn sm ${TP.days===n?'gr':'s'}" onclick="TP.days=${n};tpMod()">${n} days</button>`).join('')}</div><br><h3>Activities</h3>${d.v.map((v,i)=>`<label class="kv"><span><input type="checkbox" ${TP.sel.includes(i)?'checked':''} onchange="tpTog(${i})"> ${v[0]}</span><b>${R(v[1])}</b></label>`).join('')}<div class="doc">${kv('Flight'+(hasPlane()?' (-25% private aircraft)':''),R(c.fl))}${kv('Hotel ('+TP.days+' nights)',R(c.ho))}${kv('Food ('+TP.days+' days)',R(c.fo))}${kv('Activities',R(c.acts))}${kv('Estimated Total',`<b>${R(c.total)}</b>`)}${kv('Your Cash',R(S.cash))}</div>${ok?'':`<p class="r">${NOFUND}</p>`}<div class="row"><button class="btn s" onclick="closeModal()">CANCEL</button><button class="btn gr" ${ok?'':'disabled'} onclick="tripGo()">CONFIRM TRIP</button></div>`)}
function tpTog(i){const j=TP.sel.indexOf(i);if(j<0)TP.sel.push(i);else TP.sel.splice(j,1);tpMod()}
function hAdd(h){const L=S.life;h.id=(h.type==='trip'?'TRIP-':'VISIT-')+String(++L.hn).padStart(4,'0');L.hist.unshift(h);if(L.hist.length>100)L.hist.length=100}
function tripGo(){const d=DEST.find(x=>x.k===TP.k),c=dstCost(d,TP.days,TP.sel);if(S.cash<c.total){snd(200,.25);return toast(NOFUND,'bad')}
 const c0=S.cash,ids=[],dest=d.city+', '+d.co,rec=(amt,cat,desc,to)=>ids.push(lspend(amt,cat,desc,{to,dest}).id);
 rec(c.fl,'Travel','Flight to '+d.city,'Airline');rec(c.ho,'Hotels',`Hotel in ${d.city} (${TP.days} nights)`,'Hotel');rec(c.fo,'Restaurants',`Food in ${d.city} (${TP.days} days)`,'Local restaurants');
 const items=TP.sel.map(i=>({n:d.v[i][0],c:d.v[i][1]}));TP.sel.forEach(i=>{const v=d.v[i];rec(v[1],v[2],v[0]+' in '+d.city,v[0])});
 if(!S.life.trips.includes(d.k))S.life.trips.push(d.k);const h={type:'trip',m:S.month,k:d.k,dest,days:TP.days,fl:c.fl,ho:c.ho,fo:c.fo,acts:c.acts,total:c.total,items,tx:ids,c0,c1:S.cash};hAdd(h);coin();after();
 const st=pick([`You explored the streets of ${d.city} and discovered a local art market.`,`You enjoyed a beautiful evening in ${d.city}.`,`You visited a historic attraction in ${d.city}.`,`You tried a famous local restaurant in ${d.city}.`]);
 modal(`<h2>${d.f} ${d.city}</h2><div class="doc"><p>${st}</p>${items.length?`<p class="m">Activities: ${items.map(i=>i.n).join(', ')}</p>`:''}</div><p>Trip paid: <b>${R(c.total)}</b></p><br><div class="row"><button class="btn s" onclick="closeModal()">CLOSE</button><button class="btn gr" onclick="tripRcpt(S.life.hist[0])">VIEW TRAVEL RECEIPT</button></div>`)}
const vsrc=s=>s==='life'?{n:'Lifestyle',v:LACT}:DEST.find(x=>x.k===s);
function localMod(s){const d=vsrc(s);modal(`<h2>${s==='life'?'Lifestyle activities':d.f+' '+d.city+' activities'}</h2><p class="m">Each visit is paid once and gives a receipt.</p>`+d.v.map((v,i)=>`<div class="card"><div class="kv"><b>${v[0]}</b><b>${R(v[1])}</b></div><p class="m">${v[2]}</p><button class="btn sm gr" onclick="visitMod('${s}',${i})">VISIT</button></div>`).join('')+`<button class="btn s" onclick="closeModal()">CLOSE</button>`)}
function visitMod(s,i){const d=vsrc(s),v=d.v[i];modal(`<h2>${v[0]}</h2>${kv('Location',s==='life'?'Sunrise City':d.city)}${kv('Cost',R(v[1]))}${kv('Your Cash',R(S.cash))}${kv('Cash After',`<b class="${S.cash>=v[1]?'g':'r'}">${R(S.cash-v[1])}</b>`)}<br><div class="row"><button class="btn s" onclick="closeModal()">CANCEL</button><button class="btn gr" onclick="visitGo('${s}',${i})">CONFIRM ${R(v[1])}</button></div>`)}
function visitGo(s,i){const d=vsrc(s),v=d.v[i],c0=S.cash,dest=s==='life'?'Sunrise City':d.city+', '+d.co,r=lspend(v[1],v[2],v[0]+' in '+(s==='life'?'Sunrise City':d.city),{to:v[0],dest});if(!r)return;hAdd({type:'activity',m:S.month,dest,items:[{n:v[0],c:v[1]}],total:v[1],tx:[r.id],c0,c1:S.cash});coin();after();tripRcpt(S.life.hist[0])}
function tripRcpt(h){const rows=h.type==='trip'?[['Destination',h.dest],['Trip Duration',h.days+' Days'],['Flight',R(h.fl)],['Hotel',R(h.ho)],['Food',R(h.fo)],['Activities',R(h.acts)]]:[['Activity',h.items[0].n],['Location',h.dest]];
 modal(`<div class="rcpt"><div class="rc-h"><small>PROPERTY EMPIRE</small><h2>Travel Expense Receipt</h2></div><div class="rc-m"><span>Month ${h.m}</span><span>${h.id}</span></div>${rows.map(z=>`<div class="rc-r"><span>${z[0]}</span><b>${z[1]}</b></div>`).join('')}${h.type==='trip'?h.items.map(i=>`<div class="rc-r"><span class="m">• ${i.n}</span><b class="m">${R(i.c)}</b></div>`).join(''):''}<div class="rc-t"><span>${h.type==='trip'?'TOTAL TRIP COST':'TOTAL PAID'}</span><b>${R(h.total)}</b></div><div class="rc-ok">✓ PAID</div><div class="rc-r"><span>Previous Cash</span><b>${R(h.c0)}</b></div><div class="rc-r"><span>Current Cash</span><b>${R(h.c1)}</b></div><p class="rc-th">Transactions: ${h.tx.join(', ')}</p><button class="btn" onclick="closeModal()">CLOSE</button></div>`)}
function certMod(t,id){const it=t==='art'?S.life.art.find(x=>x.id===id):S.life.own.find(x=>x.id===id);if(!it)return;const d=t==='art'?ARTS.find(x=>x.k===it.k):LF(it.k);modal(`<div class="lic"><small>PROPERTY EMPIRE</small><h2>${t==='art'?'CERTIFICATE OF AUTHENTICITY':'CERTIFICATE OF OWNERSHIP'}</h2>${kv('Item',d.n)}${kv('Certificate No',(t==='art'?'ART-':'OWN-')+String(it.id).padStart(5,'0'))}${kv('Purchase Price',R(it.pp))}${kv('Acquired','Month '+it.m)}${t==='art'?kv('Artist',artist(d.i)):''}${kv('Status',`<b class="g">VERIFIED</b>`)}</div><br><button class="btn" onclick="closeModal()">CLOSE</button>`)}
// ---- screens ----
function vehCard(d){const own=S.life.own.some(o=>o.k===d.k);return`<div class="card">${svgOf(d)}<div class="kv"><b>${d.n}</b><b>${R(d.p)}</b></div>${kv('Maintenance',R(d.u)+'/month')}${kv('Status',own?sp('Owned','g'):sp('Available'))}<br><button class="btn ${own?'s':'gr'} sm" onclick="vMod('${d.k}')">${own?'DETAILS':'VIEW & BUY'}</button></div>`}
function ownCard(it){const d=LF(it.k),v=vVal(it);return`<div class="card">${svgOf(d)}<div class="kv"><b>${d.n}</b>${sp('Owned','g')}</div>${kv('Purchase Price',R(it.pp))}${kv('Estimated Value',`<b class="${v>=it.pp?'g':'r'}">${R(v)}</b>`)}${kv('Maintenance',R(d.u)+'/month')}${kv('This month',(it.mm||0)>=S.month?'Paid ✅':'Due at month end')}<br><div class="row"><button class="btn sm" onclick="vPay(${it.id})">PAY MAINTENANCE</button><button class="btn sm rd" onclick="vSellMod(${it.id})">SELL</button></div></div>`}
function lifeTab(){const L=S.life;
 if(LT==='ov'){const pa=lifeAssets(),lv=LVT.filter(x=>pa>=x).length-1,nx=LVT[lv+1],veh=L.own.filter(o=>LF(o.k).t!=='home').length,mo=L.own.reduce((a,o)=>a+LF(o.k).u,0);
  return`<div class="card"><h3>🌴 LIFESTYLE: ${LVN[lv]}</h3><div class="bar" style="margin:6px 0"><i style="width:${nx?Math.round((pa-LVT[lv])/(nx-LVT[lv])*100):100}%"></i></div><p class="m">${nx?'Next level at '+R(nx)+' in personal assets.':'You have reached the top lifestyle level.'}</p></div><div class="card">${kv('Personal Cash',R(S.cash))}${kv('Savings',R(S.bank))}${kv('Personal Assets',`<b>${R(pa)}</b>`)}${kv('Total Personal Expenses',`<span class="r">${R(L.spent)}</span>`)}${kv('Countries Visited',L.trips.length)}${kv('Vehicles Owned',veh)}${kv('Artworks Collected',L.art.length)}${kv('Monthly Maintenance',R(mo))}<p class="m">Assets are counted once in your net worth. Spending is tracked separately.</p></div>`}
 if(LT==='vh'){const own=L.own.filter(o=>LF(o.k).t!=='home');return`<div class="pills">${[['car','🚗 Cars'],['boat','⛵ Boats'],['plane','✈️ Planes']].map(x=>`<button class="${VT===x[0]?'on':''}" onclick="VT='${x[0]}';render()">${x[1]}</button>`).join('')}</div>`+VEH.filter(d=>d.t===VT).map(vehCard).join('')+`<h2>MY GARAGE</h2>`+(own.length?own.map(ownCard).join(''):'<div class="card">You do not own any vehicles yet.</div>')}
 if(LT==='art'){const tot=L.art.reduce((a,x)=>a+x.val,0);return`<div class="card"><h3>🖼️ ART COLLECTION</h3>${kv('Artworks Owned',L.art.length)}${kv('Collection Value',`<b>${R(tot)}</b>`)}</div>`+[...new Set(ARTS.map(a=>a.cat))].map(c=>`<h3 style="margin:12px 0 6px">${c}</h3>`+ARTS.filter(a=>a.cat===c).map(d=>{const o=L.art.find(x=>x.k===d.k);return`<div class="card">${artPic(d)}<div class="kv"><b>${d.n}</b><b>${R(d.p)}</b></div>${kv('Style · Artist',d.st+' · '+artist(d.i))}${o?kv('Estimated Value',`<b class="${o.val>=o.pp?'g':'r'}">${R(o.val)}</b>`)+`<br><div class="row"><button class="btn sm rd" onclick="aSellMod(${o.id})">SELL</button></div>`:`${kv('Status',sp('Available'))}<br><button class="btn gr sm" onclick="aMod('${d.k}')">VIEW & BUY</button>`}</div>`}).join('')).join('')}
 if(LT==='tr'){const fl=L.trips.map(k=>{const d=DEST.find(x=>x.k===k),o=OLDV[k];return d?d.f+' '+d.co:o?o[0]+' '+o[1]:''}).filter(Boolean);
  return`<div class="card"><h3>🌍 COUNTRIES VISITED (${L.trips.length})</h3><p>${fl.length?fl.join(' · '):'<span class="m">No countries visited yet.</span>'}</p></div>`+DEST.map(d=>{const c=dstCost(d,3,[]);return`<div class="card"><h3>${d.f} ${d.co.toUpperCase()} — ${d.city}</h3><p class="m">${d.ds}</p>${kv('Flight',R(c.fl))}${kv('Hotel',R(d.ho)+' / night')}${kv('Food',R(d.fo)+' / day')}${kv('Estimated 3-day trip',`<b>${R(c.total)}</b>`)}${L.trips.includes(d.k)?'<p>'+sp('Visited ✅','g')+'</p>':''}<br><div class="row"><button class="btn gr sm" onclick="tpMod('${d.k}')">PLAN TRIP</button><button class="btn s sm" onclick="localMod('${d.k}')">LOCAL ACTIVITIES</button></div></div>`}).join('')+`<h2>TRAVEL HISTORY</h2>`+(L.hist.length?L.hist.slice(0,15).map((h,i)=>`<div class="card"><div class="kv"><b>${h.type==='trip'?'✈️ '+h.dest:'🎟️ '+h.items[0].n}</b><b class="r">−${R(h.total)}</b></div><p class="m">${h.id} · Month ${h.m}${h.type==='trip'?' · '+h.days+' days':' · '+h.dest}</p><button class="btn s sm" onclick="tripRcpt(S.life.hist[${i}])">VIEW RECEIPT</button></div>`).join(''):'<div class="card">No trips or activities yet.</div>')}
 if(LT==='ls'){const homes=L.own.filter(o=>LF(o.k).t==='home');return`<h3>🏡 Personal Homes</h3>`+HOMES.map(vehCard).join('')+(homes.length?`<h2>MY HOMES</h2>`+homes.map(ownCard).join(''):'')+`<h2>LIFESTYLE ACTIVITIES</h2><div class="card"><p class="m">Treat yourself in Sunrise City.</p><button class="btn gr" onclick="localMod('life')">BROWSE ACTIVITIES</button></div>`}
 if(LT==='ex'){const l=S.fin.tx.filter(r=>r.x&&r.x.cat&&(r.k==='life'||(r.k==='asset'&&r.a<0))&&(EF==='all'||r.x.cat===EF));
  return`<div class="card"><h3>💸 PERSONAL EXPENSES</h3>${kv('Total Personal Spending',`<b class="r">${R(L.spent)}</b>`)}${kv('Personal Assets Owned',R(lifeAssets()))}<p class="m">Vehicles, homes and art are assets. They appear in this list but are counted in your assets, not as lost money.</p><select onchange="EF=this.value;render()">${['all',...EXC].map(c=>`<option value="${c}"${EF===c?' selected':''}>${c==='all'?'All categories':c}</option>`).join('')}</select></div>`+(l.length?l.slice(0,100).map(r=>`<div class="card"><div class="kv"><b>${r.x.cat}${r.k==='asset'?' · Asset':''}</b><b class="r">−${R(-r.a)}</b></div><p>${r.x.d||r.t}</p><p class="m">${r.id} · Month ${r.m}</p><button class="btn s sm" onclick="txView('${r.id}')">VIEW RECEIPT</button></div>`).join(''):'<div class="card">No personal expenses yet.</div>')}
 return`<div class="card"><h3>📄 DOCUMENTS</h3>${S.bz.lic?`<button class="btn gr" onclick="licMod()">📄 Business License</button>`:`<p class="m">Business License: unlocks at ₹30,00,000 net worth.</p>`}</div>`+(L.own.length||L.art.length?`<div class="card"><h3>Certificates</h3>${L.own.map(o=>`<div class="kv"><span>${LF(o.k).n}</span><button class="btn s sm" onclick="certMod('own',${o.id})">VIEW</button></div>`).join('')}${L.art.map(o=>`<div class="kv"><span>${ARTS.find(x=>x.k===o.k).n}</span><button class="btn s sm" onclick="certMod('art',${o.id})">VIEW</button></div>`).join('')}</div>`:'')}

render();